'use client';

import {
  useNavigation,
  useRoute,
  type RouteProp,
} from '@react-navigation/native';
import type React from 'react';
import {useEffect, useState} from 'react';
import {BackHandler, StatusBar, StyleSheet, View} from 'react-native';
import {SafeAreaView, useSafeAreaInsets} from 'react-native-safe-area-context';

import ChapterList from '@/components/learn/videoplayer/ChapterList';
import VideoPlayer from '@/components/learn/videoplayer/VideoPlayer';
import VideoSettings from '@/components/learn/videoplayer/VideoSettings';
import useAppStore from '@/core/stores';
import {useShallow} from 'zustand/react/shallow';

type VideoPlayerScreenParams = {
  chapterId?: string;
  videoId?: string;
  startPos?: number;
};

type VideoPlayerScreenRouteProp = RouteProp<
  {VideoPlayer: VideoPlayerScreenParams},
  'VideoPlayer'
>;

const VideoPlayerScreen: React.FC = () => {
  const route = useRoute<VideoPlayerScreenRouteProp>();
  const navigation = useNavigation();
  const insets = useSafeAreaInsets();

  const {chapterId, videoId, startPos} = route.params || {};

  console.log('VideoPlayerScreen params:', {chapterId, videoId, startPos});

  // Local state
  const [showChapterList, setShowChapterList] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  // Store state
  const {
    currentVideoId,
    isFullscreen,
    playVideo,
    playChapterVideos,
    getCurrentVideo,
    setIsFullscreen,

    getVideoById,
  } = useAppStore(useShallow(state => state?.playlist));

  // Handle back button
  useEffect(() => {
    const backHandler = BackHandler.addEventListener(
      'hardwareBackPress',
      () => {
        if (isFullscreen) {
          setIsFullscreen(false);
          return true;
        }
        if (showChapterList || showSettings) {
          setShowChapterList(false);
          setShowSettings(false);
          return true;
        }
        return false;
      },
    );

    return () => backHandler.remove();
  }, [isFullscreen, showChapterList, showSettings, setIsFullscreen]);

  const handleClose = () => {
    navigation.goBack();
  };

  const handleVideoSelect = (selectedVideoId: string) => {
    playVideo(selectedVideoId);
    setShowChapterList(false);
  };

  const currentVideo = getVideoById(videoId || '') ?? getCurrentVideo?.();

  if (!currentVideo) {
    return (
      <View style={styles.errorContainer}>
        <StatusBar barStyle="light-content" backgroundColor="#000" />
      </View>
    );
  }

  return (
    <SafeAreaView
      style={[styles.container, isFullscreen && styles.fullscreenContainer]}>
      <StatusBar
        barStyle="light-content"
        backgroundColor="transparent"
        translucent
        hidden={isFullscreen}
      />

      <VideoPlayer
        onClose={handleClose}
        onShowChapterList={() => setShowChapterList(true)}
        onShowSettings={() => setShowSettings(true)}
        video={currentVideo}
        startPosition={startPos ? Number(startPos) : undefined}
        chapterId={chapterId || ''}
      />

      <ChapterList
        visible={showChapterList}
        onClose={() => setShowChapterList(false)}
        onVideoSelect={handleVideoSelect}
      />

      <VideoSettings
        visible={showSettings}
        onClose={() => setShowSettings(false)}
      />
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#000',
  },
  fullscreenContainer: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    zIndex: 1000,
  },
  errorContainer: {
    flex: 1,
    backgroundColor: '#000',
    justifyContent: 'center',
    alignItems: 'center',
  },
});

export default VideoPlayerScreen;
