import {lightTheme} from '@/constants/colors';
import {NativeStackScreenProps} from '@react-navigation/native-stack';
import React, {useMemo, useState} from 'react';
import {
  Image,
  ScrollView,
  StatusBar,
  Text,
  TouchableOpacity,
  View,
} from 'react-native';
import LinearGradient from 'react-native-linear-gradient';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import Feather from 'react-native-vector-icons/Feather';
import {RootStackParamList} from '../../../navigations/MainNavigation';
import styles from './EditProfileStyles';
import BackButton from '@/components/ui/buttons/back-button';
import useAppStore from '@/core/stores';
import {useShallow} from 'zustand/react/shallow';
import { EmailInput, NameInput, PasswordInput } from '@/components/ui';
import { checkUserPassword, updateUserEmail, updateUserProfile } from '@/services/auth/authentication';
import { Toast } from '@/utils/toast';
import { launchImageLibrary } from 'react-native-image-picker';

const Colors = lightTheme;

type EditProfileScreenProps = NativeStackScreenProps<
  RootStackParamList,
  'EditProfile' // The name of this route in your RootStackParamList
>;

const EditProfile = (props: EditProfileScreenProps) => {
  const {navigation} = props;
  const {userData} = useAppStore(useShallow(state => state.user));
  const insets = useSafeAreaInsets();

  // Check if user has a profile photo
  const hasProfilePhoto = useMemo(() => {
    return !!userData?.photoURL;
  }, [userData?.photoURL]);

  // Format email to truncate if longer than 25 characters
  const formatEmail = useMemo(() => {
    const email = userData?.email || 'janewillison@gmail.com';
    return email.length > 25 ? `${email.substring(0, 22)}...` : email;
  }, [userData?.email]);

  const [formData, setFormData] = useState({
    username: userData?.displayName || 'Jane',
    email: formatEmail,
    password: '',
    profileImage: userData?.photoURL ?? undefined,
  });
    
  const isValidEmail = (email: string): boolean => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  const handleFormDataChange = (key: 'username' | 'email' | 'password' | 'profileImage', value: string | undefined) => {
    setFormData(prev => ({
      ...prev,
      [key]: value,
    }))
  }

  const handleSave = async () => {
    try {
      const isPasswordCorrect = await checkUserPassword(formData.password);
      if(isPasswordCorrect){
        if(isValidEmail(formData.email)){
          if(formData.username !== userData?.displayName){
            await updateUserProfile({displayName: formData.username})
          }
          if(formData.profileImage !== userData?.photoURL){
            await updateUserProfile({photoURL: formData.profileImage})
          }
          if(formData.email !== userData?.email){
            await updateUserEmail(formData.email, formData.password)
          }
        } else{
          throw new Error("Invaild email");
        }
      }
      navigation.goBack();
    } catch (error) {
      console.error(error);
      Toast(String(error));
    }
  };

  const handleUpdatePhoto = async () => {
    const result = await launchImageLibrary({ mediaType: 'photo' });

    if (!result.didCancel && result.assets && result.assets.length > 0) {
      const uri = result.assets[0].uri;
      handleFormDataChange('profileImage', uri);
    }
  };

  const navigateToChangePassword = () => {
    navigation.navigate('ChangePassword');
  };

  return (
    <View style={styles.mainContainer}>
      <StatusBar backgroundColor={Colors.lightGreen} barStyle="dark-content" />

      {/* Header with lightGreen background */}
      <View style={styles.headerContainer}>
        {/* Header Gradient - extracted from MainHeader */}
        <LinearGradient
          colors={['rgba(0, 0, 0, 0.5)', 'rgba(0, 0, 0, 0.2)', 'transparent']}
          style={styles.headerGradient}
          pointerEvents="none"
        />
        <View style={styles.headerContent}>
          <BackButton
            borderColor="white"
            iconColor="white"
            style={{zIndex: 5}}
          />
          <Text style={styles.headerTitle}>Edit My Profile</Text>
          <View style={{width: 24}} />
        </View>
      </View>

      <View style={styles.profileContainer}>
        {hasProfilePhoto ? (
          <Image
            source={formData.profileImage ? {uri: formData.profileImage} : undefined}
            style={styles.profileImage}
          />
        ) : (
          <View style={[styles.profileImage, styles.profileIconContainer]}>
            <Feather name="user" size={50} color={'black'} />
          </View>
        )}
        <TouchableOpacity onPress={handleUpdatePhoto} style={styles.cameraButton}>
          <Feather name="camera" size={18} color="white" />
        </TouchableOpacity>
      </View>

      <ScrollView style={{flex: 1}}>
        <View style={styles.formContainer}>
          <Text style={styles.inputLabel}>User Name</Text>
          <NameInput 
            value={formData.username}
            onChangeText={(val) => handleFormDataChange('username', val)}
          />

          <Text style={styles.inputLabel}>Email</Text>
          <EmailInput
            value={formData.email}
            onChangeText={(val) => handleFormDataChange('email', val)}
          />

          <Text style={styles.inputLabel}>Password</Text>
          <PasswordInput
            value={formData.password}
            onChangeText={(val) => handleFormDataChange('password', val)}
          />
          <View style={styles.buttonRow}>
            <TouchableOpacity
              style={styles.changePasswordBtn}
              onPress={navigateToChangePassword}>
              <Text style={styles.changePasswordText}>Change Password</Text>
            </TouchableOpacity>

            <TouchableOpacity style={styles.saveBtn} onPress={handleSave}>
              <Text style={styles.saveText}>Save</Text>
            </TouchableOpacity>
          </View>
        </View>
      </ScrollView>
    </View>
  );
};

export default EditProfile;
