// How many symptoms per row and max rows before "See More"
const SYMPTOMS_PER_ROW = 3;
const MAX_ROWS = 3;

export default function LogSymptomsScreen({navigation}: {navigation: any}) {
  const [visibility, setVisibility] = useState(false);
  const [shouldNavigateBack, setShouldNavigateBack] = useState(false);
  const [searchText, setSearchText] = useState('');
  const [selectedPhysical, setSelectedPhysical] = useState<{
    [key: string]: number;
  }>({});
  const [selectedPsychological, setSelectedPsychological] = useState<{
    [key: string]: number;
  }>({});
  const [mood, setMood] = useState(
    moodQuestions.reduce((acc, item) => ({...acc, [item.key]: 2}), {}),
  );

  // Others for physical
  const [showPhysicalOthersInput, setShowPhysicalOthersInput] = useState(false);
  const [physicalOthersText, setPhysicalOthersText] = useState('');
  const [physicalOthersCounter, setPhysicalOthersCounter] = useState(0);

  // Others for psychological
  const [showPsychologicalOthersInput, setShowPsychologicalOthersInput] =
    useState(false);
  const [psychologicalOthersText, setPsychologicalOthersText] = useState('');
  const [psychologicalOthersCounter, setPsychologicalOthersCounter] =
    useState(0);

  // Pagination for symptoms
  const [showAllPhysical, setShowAllPhysical] = useState(false);
  const [showAllPsychological, setShowAllPsychological] = useState(false);

  // Zustand recent symptoms store
  const {addRecentPhysical, addRecentPsychological, getRecentSymptoms} =
    useAppStore(state => state.recent_symptom);

  // Get recent symptoms using unified getter
  const recentSymptoms = getRecentSymptoms();

  // Filter based on search
  const filteredPhysical = physicalSymptomsList.filter(symp =>
    symp.toLowerCase().includes(searchText.toLowerCase()),
  );
  const filteredPsychological = psychologicalSymptomsList.filter(symp =>
    symp.toLowerCase().includes(searchText.toLowerCase()),
  );

  // If searching and nothing found, enable "others" button
  const physicalNoMatch =
    searchText.length > 0 && filteredPhysical.length === 0;
  const psychologicalNoMatch =
    searchText.length > 0 && filteredPsychological.length === 0;

  // Show only some symptoms unless expanded
  const visiblePhysical = showAllPhysical
    ? filteredPhysical
    : filteredPhysical.slice(0, SYMPTOMS_PER_ROW * MAX_ROWS);
  const visiblePsychological = showAllPsychological
    ? filteredPsychological
    : filteredPsychological.slice(0, SYMPTOMS_PER_ROW * MAX_ROWS);

  // Haptic feedback based on level
  const hapticOptions = {
    enableVibrateFallback: true,
    ignoreAndroidSystemSettings: false,
  };
  const triggerHapticFeedback = level => {
    if (level === 0) {
      ReactNativeHapticFeedback.trigger('impactLight', hapticOptions);
    } else if (level === 1) {
      ReactNativeHapticFeedback.trigger('impactMedium', hapticOptions);
    } else if (level === 2) {
      ReactNativeHapticFeedback.trigger('impactMedium', hapticOptions);
    } else if (level === 3) {
      ReactNativeHapticFeedback.trigger('impactHeavy', hapticOptions);
    } else if (level === 4) {
      ReactNativeHapticFeedback.trigger('impactHeavy', hapticOptions);
    }
  };

  // Symptom selection haptic feedback
  const triggerSymptomHaptic = intensity => {
    if (intensity === 1) {
      ReactNativeHapticFeedback.trigger('impactLight', hapticOptions);
    } else if (intensity === 2) {
      ReactNativeHapticFeedback.trigger('impactLight', hapticOptions);
    } else if (intensity === 3) {
      ReactNativeHapticFeedback.trigger('impactMedium', hapticOptions);
    } else if (intensity === 4) {
      ReactNativeHapticFeedback.trigger('impactMedium', hapticOptions);
    } else if (intensity >= 5) {
      ReactNativeHapticFeedback.trigger('impactHeavy', hapticOptions);
    }
  };

  // Mood slider change with haptic feedback
  const handleMoodChange = (key, value) => {
    if (mood[key] !== value) {
      triggerHapticFeedback(value);
      setMood(prev => ({...prev, [key]: value}));
    }
  };

  // Add to selected and recently used with haptic feedback
  const handlePhysicalPress = symptom => {
    const newIntensity = (selectedPhysical[symptom] || 0) + 1;
    setSelectedPhysical(prev => ({
      ...prev,
      [symptom]: newIntensity,
    }));
    triggerSymptomHaptic(newIntensity);
    addRecentPhysical(symptom);
  };

  const handlePsychologicalPress = symptom => {
    const newIntensity = (selectedPsychological[symptom] || 0) + 1;
    setSelectedPsychological(prev => ({
      ...prev,
      [symptom]: newIntensity,
    }));
    triggerSymptomHaptic(newIntensity);
    addRecentPsychological(symptom);
  };

  // Others logic with haptic feedback
  const handlePhysicalOthersPress = () => {
    ReactNativeHapticFeedback.trigger('impactLight', hapticOptions);
    setShowPhysicalOthersInput(true);
  };

  const handlePsychologicalOthersPress = () => {
    ReactNativeHapticFeedback.trigger('impactLight', hapticOptions);
    setShowPsychologicalOthersInput(true);
  };

  const incrementPhysicalOthers = () => {
    const newCount = physicalOthersCounter + 1;
    setPhysicalOthersCounter(newCount);
    triggerSymptomHaptic(newCount);
  };

  const incrementPsychologicalOthers = () => {
    const newCount = psychologicalOthersCounter + 1;
    setPsychologicalOthersCounter(newCount);
    triggerSymptomHaptic(newCount);
  };

  // Submit with haptic feedback
  const handleSubmit = () => {
    ReactNativeHapticFeedback.trigger('notificationSuccess', hapticOptions);

    const filteredPhysicalSelected = Object.entries(selectedPhysical)
      .filter(([_, count]) => count > 0)
      .map(([symptom]) => symptom);

    const filteredPsychologicalSelected = Object.entries(selectedPsychological)
      .filter(([_, count]) => count > 0)
      .map(([symptom]) => symptom);

    if (physicalOthersText.trim() && physicalOthersCounter > 0) {
      filteredPhysicalSelected.push(`Other: ${physicalOthersText.trim()}`);
    }
    if (psychologicalOthersText.trim() && psychologicalOthersCounter > 0) {
      filteredPsychologicalSelected.push(
        `Other: ${psychologicalOthersText.trim()}`,
      );
    }

    if (physicalOthersText.trim() && physicalOthersCounter > 0) {
      addRecentPhysical(`Other: ${physicalOthersText.trim()}`);
    }
    if (psychologicalOthersText.trim() && psychologicalOthersCounter > 0) {
      addRecentPsychological(`Other: ${psychologicalOthersText.trim()}`);
    }

    console.log({
      selectedPhysical: filteredPhysicalSelected,
      selectedPsychological: filteredPsychologicalSelected,
      mood,
      physicalSymptomCounts: selectedPhysical,
      psychologicalSymptomCounts: selectedPsychological,
      physicalOthersText,
      psychologicalOthersText,
      physicalOthersCounter,
      psychologicalOthersCounter,
    });
    setVisibility(true);
  };

  return (
    <>
      <StatusBar barStyle="dark-content" backgroundColor="#FFFFFF" />
      <View style={styles.container}>
        {/* Header */}
        <View style={styles.header}>
          <View style={styles.headerContent}>
            <View style={styles.headerLeft}>
              <BackButton style={styles.backButton} />
            </View>
            <View style={styles.headerCenter}>
              <Text style={styles.headerTitle}>Log Symptoms</Text>
              <Text style={styles.headerSubtitle}>
                Track your daily wellness
              </Text>
            </View>
            <View style={styles.headerRight} />
          </View>
        </View>
        <ScrollView
          style={styles.scrollView}
          contentContainerStyle={styles.scrollContent}
          showsVerticalScrollIndicator={false}>
          {/* Search Bar */}
          <View style={styles.searchContainer}>
            <TextInput
              style={styles.searchBar}
              placeholder="Search symptoms..."
              value={searchText}
              onChangeText={setSearchText}
              placeholderTextColor="#9CA3AF"
            />
          </View>

          {/* Recently Used Symptoms */}
          {recentSymptoms.length > 0 && (
            <View style={styles.section}>
              <Text style={styles.sectionTitle}>Recently Used</Text>
              <View style={styles.symptomsGrid}>
                {recentSymptoms.map((recentSymptom, idx) => (
                  <TouchableOpacity
                    key={`${recentSymptom.type}-${recentSymptom.name}`}
                    style={[
                      styles.symptomChip,
                      recentSymptom.type === 'physical'
                        ? styles.physicalSymptomChip
                        : styles.psychologicalSymptomChip,
                      (recentSymptom.type === 'physical'
                        ? (selectedPhysical[recentSymptom.name] || 0) > 0
                        : (selectedPsychological[recentSymptom.name] || 0) >
                          0) &&
                        (recentSymptom.type === 'physical'
                          ? styles.physicalSymptomChipSelected
                          : styles.psychologicalSymptomChipSelected),
                    ]}
                    onPress={() =>
                      recentSymptom.type === 'physical'
                        ? handlePhysicalPress(recentSymptom.name)
                        : handlePsychologicalPress(recentSymptom.name)
                    }
                    activeOpacity={0.7}>
                    <Text
                      style={[
                        styles.symptomChipText,
                        (recentSymptom.type === 'physical'
                          ? (selectedPhysical[recentSymptom.name] || 0) > 0
                          : (selectedPsychological[recentSymptom.name] || 0) >
                            0) && styles.symptomChipTextSelected,
                      ]}>
                      {recentSymptom.name}
                    </Text>
                    {(recentSymptom.type === 'physical'
                      ? (selectedPhysical[recentSymptom.name] || 0) > 0
                      : (selectedPsychological[recentSymptom.name] || 0) >
                        0) && (
                      <View style={styles.intensityBadge}>
                        <Text style={styles.intensityBadgeText}>
                          {recentSymptom.type === 'physical'
                            ? selectedPhysical[recentSymptom.name]
                            : selectedPsychological[recentSymptom.name]}
                        </Text>
                      </View>
                    )}
                  </TouchableOpacity>
                ))}
              </View>
            </View>
          )}

          {/* Physical Symptoms */}
          <View style={styles.section}>
            <View style={styles.sectionHeader}>
              <Text style={styles.sectionTitle}>Physical Symptoms</Text>
              <Text style={styles.sectionSubtitle}>
                Tap to select, tap again to increase intensity
              </Text>
            </View>
            <View style={styles.symptomsGrid}>
              {visiblePhysical.map((symptom, idx) => {
                const counter = selectedPhysical[symptom] || 0;
                const isSelected = counter > 0;
                return (
                  <TouchableOpacity
                    key={symptom}
                    style={[
                      styles.symptomChip,
                      styles.physicalSymptomChip,
                      isSelected && styles.physicalSymptomChipSelected,
                    ]}
                    onPress={() => handlePhysicalPress(symptom)}
                    activeOpacity={0.7}>
                    <Text
                      style={[
                        styles.symptomChipText,
                        isSelected && styles.symptomChipTextSelected,
                      ]}>
                      {symptom}
                    </Text>
                    {counter > 0 && (
                      <View style={styles.intensityBadge}>
                        <Text style={styles.intensityBadgeText}>{counter}</Text>
                      </View>
                    )}
                  </TouchableOpacity>
                );
              })}

              {/* "Others" button */}
              {physicalNoMatch && !showPhysicalOthersInput && (
                <TouchableOpacity
                  style={styles.othersChip}
                  onPress={handlePhysicalOthersPress}
                  activeOpacity={0.7}>
                  <Text style={styles.othersChipText}>+ Add Custom</Text>
                </TouchableOpacity>
              )}

              {/* "Others" input */}
              {showPhysicalOthersInput && (
                <View style={styles.customInputContainer}>
                  <TextInput
                    placeholder="Describe your symptom..."
                    placeholderTextColor="#9CA3AF"
                    value={physicalOthersText}
                    onChangeText={setPhysicalOthersText}
                    style={styles.customInput}
                    multiline
                  />
                  <TouchableOpacity
                    style={styles.addButton}
                    onPress={incrementPhysicalOthers}
                    activeOpacity={0.7}>
                    <Text style={styles.addButtonText}>Add</Text>
                  </TouchableOpacity>
                  {physicalOthersCounter > 0 && (
                    <View style={styles.intensityBadge}>
                      <Text style={styles.intensityBadgeText}>
                        {physicalOthersCounter}
                      </Text>
                    </View>
                  )}
                </View>
              )}
            </View>
            {/* See more/less button */}
            {filteredPhysical.length > SYMPTOMS_PER_ROW * MAX_ROWS && (
              <TouchableOpacity
                style={{marginTop: 8}}
                onPress={() => {
                  ReactNativeHapticFeedback.trigger(
                    'impactLight',
                    hapticOptions,
                  );
                  setShowAllPhysical(v => !v);
                }}>
                <Text style={{color: Colors.lightGreen, fontWeight: '600'}}>
                  {showAllPhysical ? 'See Less' : 'See More'}
                </Text>
              </TouchableOpacity>
            )}
          </View>

          {/* Psychological Symptoms */}
          <View style={styles.section}>
            <View style={styles.sectionHeader}>
              <Text style={styles.sectionTitle}>Psychological Symptoms</Text>
              <Text style={styles.sectionSubtitle}>
                Tap to select, tap again to increase intensity
              </Text>
            </View>
            <View style={styles.symptomsGrid}>
              {visiblePsychological.map((symptom, idx) => {
                const counter = selectedPsychological[symptom] || 0;
                const isSelected = counter > 0;
                return (
                  <TouchableOpacity
                    key={symptom}
                    style={[
                      styles.symptomChip,
                      styles.psychologicalSymptomChip,
                      isSelected && styles.psychologicalSymptomChipSelected,
                    ]}
                    onPress={() => handlePsychologicalPress(symptom)}
                    activeOpacity={0.7}>
                    <Text
                      style={[
                        styles.symptomChipText,
                        isSelected && styles.symptomChipTextSelected,
                      ]}>
                      {symptom}
                    </Text>
                    {counter > 0 && (
                      <View style={styles.intensityBadge}>
                        <Text style={styles.intensityBadgeText}>{counter}</Text>
                      </View>
                    )}
                  </TouchableOpacity>
                );
              })}

              {/* "Others" button */}
              {psychologicalNoMatch && !showPsychologicalOthersInput && (
                <TouchableOpacity
                  style={styles.othersChip}
                  onPress={handlePsychologicalOthersPress}
                  activeOpacity={0.7}>
                  <Text style={styles.othersChipText}>+ Add Custom</Text>
                </TouchableOpacity>
              )}

              {/* "Others" input */}
              {showPsychologicalOthersInput && (
                <View style={styles.customInputContainer}>
                  <TextInput
                    placeholder="Describe your symptom..."
                    placeholderTextColor="#9CA3AF"
                    value={psychologicalOthersText}
                    onChangeText={setPsychologicalOthersText}
                    style={styles.customInput}
                    multiline
                  />
                  <TouchableOpacity
                    style={styles.addButton}
                    onPress={incrementPsychologicalOthers}
                    activeOpacity={0.7}>
                    <Text style={styles.addButtonText}>Add</Text>
                  </TouchableOpacity>
                  {psychologicalOthersCounter > 0 && (
                    <View style={styles.intensityBadge}>
                      <Text style={styles.intensityBadgeText}>
                        {psychologicalOthersCounter}
                      </Text>
                    </View>
                  )}
                </View>
              )}
            </View>
            {/* See more/less button */}
            {filteredPsychological.length > SYMPTOMS_PER_ROW * MAX_ROWS && (
              <TouchableOpacity
                style={{marginTop: 8}}
                onPress={() => {
                  ReactNativeHapticFeedback.trigger(
                    'impactLight',
                    hapticOptions,
                  );
                  setShowAllPsychological(v => !v);
                }}>
                <Text style={{color: Colors.lightGreen, fontWeight: '600'}}>
                  {showAllPsychological ? 'See Less' : 'See More'}
                </Text>
              </TouchableOpacity>
            )}
          </View>

          {/* Mood Assessment Section */}
          <View style={styles.section}>
            <View style={styles.sectionHeader}>
              <Text style={styles.sectionTitle}>Mood Assessment</Text>
              <Text style={styles.sectionSubtitle}>
                Rate how you're feeling today
              </Text>
            </View>
            {moodQuestions.map(q => (
              <View key={q.key} style={styles.moodItem}>
                <Text style={styles.moodQuestion}>{q.question}</Text>
                <View style={styles.sliderContainer}>
                  <View style={styles.sliderLabels}>
                    <Text style={styles.sliderLabelLeft}>{q.left}</Text>
                    <Text style={styles.sliderLabelRight}>{q.right}</Text>
                  </View>
                  <Slider
                    style={styles.slider}
                    minimumValue={0}
                    maximumValue={4}
                    step={1}
                    value={mood[q.key]}
                    onValueChange={value => handleMoodChange(q.key, value)}
                    minimumTrackTintColor={Colors.lightGreen}
                    maximumTrackTintColor="#E5E7EB"
                    thumbTintColor={Colors.lightGreen}
                  />
                </View>
              </View>
            ))}
          </View>
        </ScrollView>
        {/* Submit Button */}
        <View style={styles.submitContainer}>
          <TouchableOpacity
            style={styles.submitButton}
            onPress={handleSubmit}
            activeOpacity={0.8}>
            <Text style={styles.submitButtonText}>Save Entry</Text>
          </TouchableOpacity>
        </View>
      </View>

      <AlertBox
        visible={visibility}
        title="Success"
        message="Mood and symptoms logged successfully!"
        onClose={() => {
          setVisibility(false);

          setShouldNavigateBack(true);
        }}
        onModalHide={() => {
          if (shouldNavigateBack) {
            setShouldNavigateBack(false);
            navigation.goBack();
          }
        }}
      />
    </>
  );
}

