import {useMemo, useCallback} from 'react';
import {
  View,
  ScrollView,
  StyleSheet,
  StatusBar,
  Text,
  TouchableOpacity,
  Image,
} from 'react-native';
import {lightTheme} from '../../constants/colors';
import {useNavigation, useRoute} from '@react-navigation/native';
import {StackNavigationProp} from '@react-navigation/stack';
import Styles from './LearnStyle';
import FONT_FAMILIES from '@/constants/fonts';
import Colors from '@/constants/colors';
import BackButton from '@/components/ui/buttons/back-button';
import Ionicons from 'react-native-vector-icons/Ionicons';

function getVideoActivityPattern(videos: any[], _activities: any[]) {
  const cards = [];
  for (let i = 0; i < videos.length; i++) {
    const video = videos[i];
    cards.push({...video, _type: 'video'});
    const activity = videos[i].postActivities && videos[i].postActivities[0];
    if (activity) {
      cards.push({
        ...activity,
        _type: 'activity',
        title: activity.question,
      });
    }
  }
  return cards;
}

type RootStackParamList = {
  VideoPlayer: {
    videoId: string;
    videoUrl: string;
    srtUrl: string;
    title: string;
    chapterId?: string;
    startPos?: number;
  };
  ActivityDetails: {
    activity: any;
    activityType: any;
    title: any;
    thumbnailUrl?: any;
  };
};

const LearnModuleShowcaseScreen = () => {
  const navigation = useNavigation<StackNavigationProp<RootStackParamList>>();
  const route = useRoute();
  const {module} = route.params as {module: any};

  const cards = useMemo(() => {
    const activities = module.videos.flatMap(
      (video: any) => video.postActivities || [],
    );
    return getVideoActivityPattern(module.videos, activities);
  }, [module]);

  const ContentCard = useCallback(
    ({
      title,
      subtitle,
      image,
      tag,
      progress,
      duration,
      onPress,
      isStressCard = false,
    }: {
      title: string;
      subtitle?: string;
      image: any;
      tag?: string;
      progress?: number;
      duration?: string;
      onPress: () => void;
      isStressCard?: boolean;
    }) => (
      <TouchableOpacity
        style={[
          isStressCard ? Styles.stressContentCard : Styles.contentCard,
          styles.fullWidthCard,
        ]}
        onPress={onPress}>
        <View
          style={
            isStressCard ? Styles.stressCardContainer : Styles.cardContainer
          }>
          <Image
            source={typeof image === 'string' ? {uri: image} : image}
            style={isStressCard ? Styles.stressCardImage : Styles.cardImage}
            resizeMode="cover"
          />
          <View
            style={
              isStressCard ? Styles.stressCardContent : Styles.cardContent
            }>
            {tag && (
              <View style={Styles.tagContainer}>
                <Text style={Styles.tagText}>{tag}</Text>
              </View>
            )}
            <Text
              style={isStressCard ? Styles.stressCardTitle : Styles.cardTitle}
              numberOfLines={isStressCard ? 2 : 1}>
              {title}
            </Text>
            <View style={Styles.authorContainer}>
              {subtitle && (
                <Text style={Styles.cardSubtitle}>by {subtitle}</Text>
              )}
              {duration && <Text style={Styles.cardDuration}>{duration}</Text>}
            </View>
            {progress !== undefined && progress !== null && (
              <View style={Styles.progressContainer}>
                <View style={[Styles.progressBar, {width: `${progress}%`}]} />
              </View>
            )}
            {!progress && duration && duration.includes('mins') && (
              <View style={Styles.playButton}>
                <Ionicons name="play" size={18} color={Colors.white} />
                <Text style={Styles.playText}>Play</Text>
              </View>
            )}
          </View>
        </View>
      </TouchableOpacity>
    ),
    [],
  );

  const handleCardPress = (item: any) => {
    if (item._type === 'video') {
      navigation.navigate('VideoPlayer', {
        videoId: item.id,
        videoUrl: item.videoUrl,
        srtUrl: item.srtUrl,
        title: item.title,
        chapterId: item.id,
        startPos: 0,
      });
    } else {
      navigation.navigate('ActivityDetails', {
        activity: item,
        activityType: item.type,
        title: item.title,
        thumbnailUrl: item.thumbnailUrl,
      });
    }
  };

  const renderCard = (item: any, index: number) => {
    const isVideo = item._type === 'video';
    return (
      <ContentCard
        key={index}
        title={item.title}
        subtitle={isVideo ? item.author : undefined}
        image={item.thumbnailUrl}
        tag={isVideo ? 'Video' : 'Activity'}
        duration={isVideo ? item.duration : undefined}
        onPress={() => handleCardPress(item)}
      />
    );
  };

  return (
    <View style={styles.container}>
      <StatusBar backgroundColor={Colors.white} barStyle="dark-content" />
      <View style={styles.header}>
        <BackButton onPress={() => navigation.goBack()} />
        <View style={styles.headerContent}>
          <Text style={styles.headerTitle}>{module.title}</Text>
        </View>
      </View>

      <ScrollView
        style={styles.scrollView}
        showsVerticalScrollIndicator={false}
        contentContainerStyle={styles.scrollContent}>
        <View style={styles.listContent}>
          {cards.map((item, index) => renderCard(item, index))}
        </View>
      </ScrollView>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: Colors.white,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 20,
    paddingTop: 60,
    paddingBottom: 20,
    backgroundColor: Colors.white,
    borderBottomWidth: 1,
    borderBottomColor: '#F3F4F6',
  },
  headerContent: {
    flex: 1,
    marginLeft: -30,
    alignItems: 'center',
    justifyContent: 'center',
  },
  headerTitle: {
    fontSize: 24,
    fontWeight: '600',
    color: '#1F2937',
    fontFamily: FONT_FAMILIES.YoungSerifRegular,
    marginBottom: 8,
  },
  statsRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
  },
  statBadge: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#F0F9FF',
    paddingHorizontal: 8,
    paddingVertical: 4,
    borderRadius: 12,
    gap: 4,
  },
  statText: {
    fontSize: 12,
    color: lightTheme.primary,
    fontWeight: '500',
  },
  scrollView: {
    flex: 1,
    backgroundColor: '#FAFAFA',
  },
  scrollContent: {
    padding: 16,
    paddingBottom: 32,
  },
  listContent: {
    gap: 16,
  },
  fullWidthCard: {
    width: '100%',
    marginHorizontal: 0,
    marginBottom: 0,
  },
});

export default LearnModuleShowcaseScreen;
