import {FONT_FAMILIES, lightTheme} from '@/constants';
import DateTimePicker from '@react-native-community/datetimepicker';
import moment from 'moment';
import React, {useCallback, useState} from 'react';
import {
  Modal,
  Platform,
  StyleSheet,
  Text,
  TextStyle,
  View,
  ViewStyle,
} from 'react-native';
import {Gesture, GestureDetector} from 'react-native-gesture-handler';
import Animated, {
  runOnJS,
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
} from 'react-native-reanimated';
import Feather from 'react-native-vector-icons/Feather';

// Type definitions
interface DatePickerTheme {
  primary: string;
  primaryLight: string;
  background: string;
  surface: string;
  textDark: string;
  textLight: string;
  border: string;
  shadow: string;
}

interface GenericDatePickerProps {
  label?: string;
  value?: moment.Moment | undefined;
  onDateChange: (date: moment.Moment) => void;
  placeholder?: string;
  format?: string;
  minimumDate?: Date;
  maximumDate?: Date;
  theme?: Partial<DatePickerTheme>;
  disabled?: boolean;
  required?: boolean;
  error?: string;
  containerStyle?: ViewStyle;
  inputStyle?: ViewStyle;
  labelStyle?: TextStyle;
  errorStyle?: TextStyle;
  mode?: 'date' | 'time' | 'datetime';
  display?: 'default' | 'spinner' | 'calendar' | 'clock';
}

const defaultTheme: DatePickerTheme = {
  primary: lightTheme.primary,
  primaryLight: lightTheme.primaryLight,
  background: '#FFFFFF',
  surface: '#FFFFFF',
  textDark: lightTheme.textDark,
  textLight: lightTheme.textLight,
  border: lightTheme.primary,
  shadow: '#000000',
};

const GenericDatePicker: React.FC<GenericDatePickerProps> = ({
  label,
  value,
  onDateChange,
  placeholder = 'Select date',
  format = 'DD/MM/YYYY',
  minimumDate,
  maximumDate,
  theme = {},
  disabled = false,
  required = false,
  error,
  containerStyle,
  inputStyle,
  labelStyle,
  errorStyle,
  mode = 'date',
  display = Platform.OS === 'ios' ? 'spinner' : 'default',
}) => {
  const [isModalVisible, setModalVisible] = useState<boolean>(false);
  const [tempDate, setTempDate] = useState<Date>(
    value ? value.toDate() : new Date(),
  );

  const mergedTheme = {...defaultTheme, ...theme};

  // Animation values
  const scale = useSharedValue(1);
  const opacity = useSharedValue(0);
  const translateY = useSharedValue(50);
  const backdropOpacity = useSharedValue(0);

  const formatDate = useCallback(
    (date: moment.Moment): string => {
      if (!date) return '';
      return date.format(format);
    },
    [format],
  );

  const handleDateChange = useCallback(
    (event: any, selectedDate?: Date) => {
      if (Platform.OS === 'android') {
        setModalVisible(false);
        hideModal();
      }

      if (selectedDate) {
        setTempDate(selectedDate);
        if (Platform.OS === 'android') {
          onDateChange(moment(selectedDate));
        }
      }
    },
    [onDateChange],
  );

  const showModal = useCallback(() => {
    setModalVisible(true);
    opacity.value = withTiming(1, {duration: 300});
    translateY.value = withSpring(0, {damping: 15, stiffness: 150});
    backdropOpacity.value = withTiming(0.5, {duration: 300});
  }, []);

  const hideModal = useCallback(() => {
    opacity.value = withTiming(0, {duration: 200});
    translateY.value = withTiming(50, {duration: 200});
    backdropOpacity.value = withTiming(0, {duration: 200}, () => {
      runOnJS(setModalVisible)(false);
    });
  }, []);

  const handleConfirm = useCallback(() => {
    onDateChange(moment(tempDate));
    hideModal();
  }, [tempDate, onDateChange, hideModal]);

  const handleCancel = useCallback(() => {
    setTempDate(value ? value.toDate() : new Date());
    hideModal();
  }, [value, hideModal]);

  // Gesture for input tap
  const tapGesture = Gesture.Tap()
    .enabled(!disabled)
    .onBegin(() => {
      scale.value = withSpring(0.95, {damping: 15, stiffness: 400});
    })
    .onFinalize(() => {
      scale.value = withSpring(1, {damping: 15, stiffness: 400});
      if (!disabled) {
        runOnJS(showModal)();
      }
    });

  // Animated styles
  const inputAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{scale: scale.value}],
  }));

  const modalAnimatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{translateY: translateY.value}],
  }));

  const backdropAnimatedStyle = useAnimatedStyle(() => ({
    opacity: backdropOpacity.value,
  }));

  return (
    <View style={[styles.container, containerStyle]}>
      {label && (
        <Text style={[styles.label, labelStyle]}>
          {label}
          {required && <Text style={styles.requiredIndicator}>*</Text>}
        </Text>
      )}

      <GestureDetector gesture={tapGesture}>
        <Animated.View style={inputAnimatedStyle}>
          <View style={[styles.inputContainer, inputStyle]}>
            <Feather
              name="calendar"
              size={20}
              color={mergedTheme.primary}
              style={styles.calendarIcon}
            />
            <Text style={styles.dateText}>
              {value ? formatDate(value) : placeholder}
            </Text>
          </View>
        </Animated.View>
      </GestureDetector>

      {error && <Text style={[styles.errorText, errorStyle]}>{error}</Text>}

      {Platform.OS === 'ios' ? (
        <Modal
          visible={isModalVisible}
          transparent
          animationType="none"
          onRequestClose={handleCancel}>
          <View style={styles.modalContainer}>
            <Animated.View style={[styles.backdrop, backdropAnimatedStyle]} />

            <Animated.View style={[styles.modalContent, modalAnimatedStyle]}>
              <View style={styles.modalHeader}>
                <Text style={styles.modalTitle}>
                  {mode === 'date'
                    ? 'Select Date'
                    : mode === 'time'
                    ? 'Select Time'
                    : 'Select Date & Time'}
                </Text>
              </View>

              <DateTimePicker
                value={tempDate}
                mode={mode}
                display={display}
                onChange={handleDateChange}
                minimumDate={minimumDate}
                maximumDate={maximumDate}
                style={{backgroundColor: mergedTheme.background}}
              />

              <View style={styles.modalButtons}>
                <GestureDetector
                  gesture={Gesture.Tap().onEnd(() => runOnJS(handleCancel)())}>
                  <Animated.View
                    style={[styles.modalButton, styles.cancelButton]}>
                    <Text style={styles.cancelButtonText}>Cancel</Text>
                  </Animated.View>
                </GestureDetector>

                <GestureDetector
                  gesture={Gesture.Tap().onEnd(() => runOnJS(handleConfirm)())}>
                  <Animated.View
                    style={[styles.modalButton, styles.confirmButton]}>
                    <Text style={styles.confirmButtonText}>Confirm</Text>
                  </Animated.View>
                </GestureDetector>
              </View>
            </Animated.View>
          </View>
        </Modal>
      ) : (
        isModalVisible && (
          <DateTimePicker
            value={tempDate}
            mode={mode}
            display={display}
            onChange={handleDateChange}
            minimumDate={minimumDate}
            maximumDate={maximumDate}
          />
        )
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginBottom: 25,
  },
  label: {
    fontFamily: FONT_FAMILIES.LatoRegular,
    fontSize: 16,
    color: defaultTheme.textDark,
    marginBottom: 10,
    fontWeight: '600',
  },
  requiredIndicator: {
    color: '#FF3B30',
    marginLeft: 4,
  },
  inputContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 15,
    paddingHorizontal: 20,
    borderColor: defaultTheme.border,
    // borderColor: error ? '#FF3B30' : defaultTheme.border,
    borderWidth: 1,
    borderRadius: 12,
    backgroundColor: defaultTheme.surface,
    // opacity: disabled ? 0.6 : 1,
    // opacity: disabled ? 0.6 : 1,
  },
  calendarIcon: {
    marginRight: 12,
  },
  dateText: {
    flex: 1,
    fontSize: 16,
    fontFamily: FONT_FAMILIES.LatoRegular,
    color: defaultTheme.textDark,
    // color: value ? defaultTheme.textDark : defaultTheme.textLight,
  },
  errorText: {
    fontSize: 14,
    color: '#FF3B30',
    marginTop: 4,
    fontFamily: FONT_FAMILIES.LatoRegular,
  },
  modalContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  backdrop: {
    ...StyleSheet.absoluteFillObject,
    backgroundColor: 'black',
  },
  modalContent: {
    backgroundColor: defaultTheme.background,
    borderRadius: 20,
    padding: 24,
    margin: 20,
    minWidth: 320,
    shadowColor: defaultTheme.shadow,
    shadowOffset: {
      width: 0,
      height: 8,
    },
    shadowOpacity: 0.25,
    shadowRadius: 16,
    elevation: 8,
  },
  modalHeader: {
    alignItems: 'center',
    marginBottom: 24,
  },
  modalTitle: {
    fontSize: 20,
    fontWeight: '600',
    color: defaultTheme.textDark,
    fontFamily: FONT_FAMILIES.LatoRegular,
  },
  modalButtons: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginTop: 24,
    gap: 12,
  },
  modalButton: {
    flex: 1,
    paddingVertical: 14,
    borderRadius: 12,
    alignItems: 'center',
  },
  cancelButton: {
    backgroundColor: '#F5F5F5',
    borderWidth: 1,
    borderColor: defaultTheme.border,
  },
  confirmButton: {
    backgroundColor: defaultTheme.primary,
  },
  cancelButtonText: {
    color: defaultTheme.textDark,
    fontSize: 16,
    fontWeight: '600',
    fontFamily: FONT_FAMILIES.LatoRegular,
  },
  confirmButtonText: {
    color: '#FFFFFF',
    fontSize: 16,
    fontWeight: '600',
    fontFamily: FONT_FAMILIES.LatoRegular,
  },
});

export default GenericDatePicker;
