import {TouchableOpacity, View} from 'react-native';
import Emoji1 from '../../assets/images/emoji/e1.svg';
import Emoji2 from '../../assets/images/emoji/e2.svg';
import Emoji3 from '../../assets/images/emoji/e3.svg';
import Emoji4 from '../../assets/images/emoji/e4.svg';
import Emoji5 from '../../assets/images/emoji/e5.svg';
import Emoji6 from '../../assets/images/emoji/e6.svg';
import {Text} from 'react-native';
import Colors from '@/constants/colors';
import {useState} from 'react';
import {
  fetchSymptomRecordCounts,
  insertSymptomTrackerRecord,
} from '@/services/sqlite/feminine-health';

const MoodList = [
  {id: '1', SvgComponent: Emoji1, MoodName: 'Cranky'},
  {id: '2', SvgComponent: Emoji2, MoodName: 'Stressed'},
  {id: '3', SvgComponent: Emoji3, MoodName: 'Down'},
  {id: '4', SvgComponent: Emoji4, MoodName: 'Wiped'},
  {id: '5', SvgComponent: Emoji5, MoodName: 'Serene'},
  {id: '6', SvgComponent: Emoji6, MoodName: 'Joyful'},
];

const Moods = () => {
  const [currentMood, setCurrentMood] = useState('');
  return (
    <View
      style={{
        height: 90,
        marginHorizontal: 10,
        flexDirection: 'row',
        alignItems: 'flex-start',
        justifyContent: 'space-between',
        paddingHorizontal: 5,
      }}>
      {MoodList.map(item => {
        const SvgComponent = item.SvgComponent;
        return (
          <TouchableOpacity
            key={item.id}
            style={{
              zIndex: 1,
              alignItems: 'center',
              justifyContent: 'flex-start',
              opacity: currentMood !== '' && currentMood !== item.id ? 0.2 : 1,
            }}
            onPress={async () => {
              setCurrentMood(item.id);
              await insertSymptomTrackerRecord({
                symptom_type: 'Mood',
                symptom: `${item.id}`,
                count: 0,
              });
            }}>
            <View
              style={{
                height: 60,
                width: 60,
                borderRadius: 30,
                justifyContent: 'center',
                alignItems: 'center',
              }}>
              <SvgComponent width={48} height={48} />
            </View>
            <Text
              style={{
                fontSize: 12,
                color: Colors.black,
                textAlign: 'center',
                marginTop: 5,
                fontWeight: 'normal',
                fontFamily: 'Lato-Regular',
              }}>
              {item.MoodName}
            </Text>
          </TouchableOpacity>
        );
      })}
    </View>
  );
};

export default Moods;
