import Button from '@/components/ui/buttons/button';
import AlertBox from '@/components/ui/modal/alert-box';
import {FONT_FAMILIES, IMAGES, lightTheme} from '@/constants';
import useAppStore from '@/core/stores';
import {useState} from 'react';
import {
  Dimensions,
  Image,
  Text,
  TouchableOpacity,
  View,
  StyleSheet,
} from 'react-native';

interface MentalHealthSymptomTwoProps {
  onNext: () => void;
}

const emojies = [
  {image: IMAGES.emo_scale_1, value: 1},
  {image: IMAGES.emo_scale_2, value: 2},
  {image: IMAGES.emo_scale_3, value: 3},
  {image: IMAGES.emo_scale_4, value: 4},
  {image: IMAGES.emo_scale_5, value: 5},
  {image: IMAGES.emo_scale_6, value: 6},
];

const {width} = Dimensions.get('screen');

const MentalHealthSymptomTwo: React.FC<MentalHealthSymptomTwoProps> = ({
  onNext,
}) => {
  const {addQuiz} = useAppStore(state => state.engagement);

  const [emoValue, setValue] = useState(0);

  // Alert box states
  const [alertVisible, setAlertVisible] = useState(false);
  const [alertTitle, setAlertTitle] = useState('');
  const [alertMessage, setAlertMessage] = useState('');

  const showAlert = (title: string, message: string) => {
    setAlertTitle(title);
    setAlertMessage(message);
    setAlertVisible(true);
  };

  const onContinue = () => {
    if (emoValue) {
      const emoValData = {
        id: 13,
        question: `How bad do your symptoms get? (rate out of 6)`,
        answer: emoValue,
      };
      addQuiz(emoValData);
      onNext();
    } else {
      showAlert('Error', 'Please select all the answers.');
    }
  };

  return (
    <>
      <View style={styles.container}>
        <View style={styles.questionContainer}>
          <Text style={styles.questionText}>How bad do your symptoms get?</Text>

          <View style={styles.scaleLabels}>
            <Text style={styles.scaleLabel}>I'm ok</Text>
            <Text style={styles.scaleLabel}>I feel miserable</Text>
          </View>

          <View style={styles.emojiContainer}>
            {emojies.map(({image, value}, index) => (
              <TouchableOpacity
                key={index}
                onPress={() => setValue(value)}
                style={[
                  styles.emojiButton,
                  value === emoValue && styles.selectedEmoji,
                ]}>
                <Image
                  style={[
                    styles.emojiImage,
                    value === emoValue && {tintColor: lightTheme.primary},
                  ]}
                  source={image}
                />
              </TouchableOpacity>
            ))}
          </View>
        </View>

        <View style={styles.buttonContainer}>
          <Button
            text="Continue"
            onPress={onContinue}
            backgroundColor={lightTheme.primary}
            textColor="white"
            style={styles.continueButton}
          />
        </View>
      </View>

      <AlertBox
        visible={alertVisible}
        title={alertTitle}
        message={alertMessage}
        onClose={() => setAlertVisible(false)}
        onModalHide={() => {}}
      />
    </>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    width: '100%',
    paddingHorizontal: 10,
  },
  questionContainer: {
    marginBottom: 40,
  },
  questionText: {
    fontFamily: FONT_FAMILIES.LatoRegular,
    fontWeight: 'bold',
    fontSize: 20,
    color: lightTheme.textDark,
    textAlign: 'center',
    marginBottom: 20,
    lineHeight: 28,
  },
  scaleLabels: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 20,
  },
  scaleLabel: {
    fontSize: 14,
    fontFamily: FONT_FAMILIES.LatoRegular,
    color: lightTheme.textMild,
  },
  emojiContainer: {
    flexDirection: 'row',
    justifyContent: 'space-around',
    flexWrap: 'wrap',
    marginBottom: 20,
  },
  emojiButton: {
    padding: 8,
    borderRadius: 12,
    marginBottom: 10,
  },
  selectedEmoji: {
    backgroundColor: lightTheme.primaryLight,
  },
  emojiImage: {
    width: width * 0.1,
    height: width * 0.1,
  },
  answersContainer: {
    alignItems: 'center',
  },
  answerButton: {
    width: '100%',
    marginBottom: 15,
    height: 55,
  },
  selectedButton: {
    borderWidth: 2,
    borderColor: lightTheme.primary,
  },
  unselectedButton: {
    borderWidth: 1,
    borderColor: lightTheme.buttonBorder,
  },
  buttonContainer: {
    flex: 1,
    justifyContent: 'flex-end',
    paddingBottom: 20,
  },
  continueButton: {
    width: '100%',
    height: 55,
  },
});

export default MentalHealthSymptomTwo;
