import MainHeader from '@/components/common/headers/MainHeader';
import Colors from '@/constants/colors';
import {IMAGES} from '@/constants/images';
import {
  fetchGeneralMessages,
  insertGeneralMessage,
} from '@/services/sqlite/chat-messages';
import React, {useEffect, useRef, useState} from 'react';
import {
  FlatList,
  Image,
  KeyboardAvoidingView,
  Platform,
  SafeAreaView,
  StatusBar,
  Text,
  TouchableOpacity,
  View,
} from 'react-native';
import {IconButton, TextInput} from 'react-native-paper';
import Spinner from 'react-native-spinkit';

import {LucideSend, LucideShare, LucideSquare} from 'lucide-react-native';
import Share from 'react-native-share';
import {captureRef} from 'react-native-view-shot';

// Import styles
import useChatActions from '@/hooks/use-chat-actions';
import styles from './ChatStyle';

type ChatCardProps = {
  message: string;
  dateTime?: string;
  userName?: string;
};

const ChatCard = React.forwardRef<any, ChatCardProps>(
  ({message, dateTime, userName}, ref) => (
    <View ref={ref} style={styles.card}>
      {/* Logo at top left */}
      <View style={styles.logoContainer}>
        <Image source={IMAGES.logo} style={styles.logo} />
        <Image
          source={require('../../assets/images/synapsis_logo.png')}
          style={styles.logo}
        />
      </View>
      {/* Message bubble */}
      <View style={styles.messageBubble}>
        <Text style={styles.messageText}>{message}</Text>
      </View>
      {/* Footer: User name (left), Date/time (center, optional), Myteal (right) */}
      <View style={styles.cardFooter}>
        <Text style={styles.footerUserText}>
          {userName ? `@${userName}` : ''}
        </Text>
        <Text style={styles.footerDateText}>{dateTime || ''}</Text>
        <Text style={styles.footerBrandText}>Myteal</Text>
      </View>
    </View>
  ),
);

// Predefined questions for quick chat starts
const PREDEFINED_QUESTIONS = [
  'How much should I drink during periods?',
  'Is smoking bad for menstrual health?',
  'What foods help with period cramps?',
  'How to manage mood swings during periods?',
  'Best exercises during menstruation?',
  'How to track my cycle effectively?',
];

const Chat = (props: any) => {
  const flatListRef = useRef<FlatList>(null);

  // Predefined questions state
  const [showPredefinedQuestions, setShowPredefinedQuestions] = useState(true);

  const {
    messages,
    loading,
    lastGreeted,
    userData,
    userInput,
    setLastGreeted,
    handleStop,
    sendMessage,
    setMessages,
    setAnimatedText,
    setUserInput,
  } = useChatActions({onUpdateMessage: insertGeneralMessage});

  // Handle predefined question selection
  const handlePredefinedQuestion = (question: string) => {
    setUserInput(question);
    setShowPredefinedQuestions(false);
    // Auto-send the message after a short delay
    setTimeout(() => {
      sendMessage();
    }, 100);
  };

  const capitalizeFirstLetter = (name: string) => {
    return name.charAt(0).toUpperCase() + name.slice(1);
  };

  const getCurrentDate = (): string => {
    const date = new Date();
    return date.toISOString().split('T')[0] || '';
  };

  const getTimeOfDayGreeting = () => {
    const currentHour = new Date().getHours();
    if (currentHour < 12) {
      return 'Good Morning';
    } else if (currentHour < 18) {
      return 'Good Afternoon';
    } else {
      return 'Good Evening';
    }
  };

  useEffect(() => {
    const checkAndShowGreetingMessage = async () => {
      try {
        const currentDate = getCurrentDate();

        if (lastGreeted !== currentDate) {
          setAnimatedText(true);
          const firstName = capitalizeFirstLetter(userData?.displayName ?? '');
          const greetingTime = getTimeOfDayGreeting();
          const greetingMessage = `${greetingTime} ${firstName}!\nHere is your sleep summary:\n• Sleep Duration: 7:34 Hrs\n• REM: 2:27 Hrs, Deep: 1:45 Hrs\n• Resting Heart Rate: 58 BPM`;
          await insertGeneralMessage({
            role: 'assistant',
            message: greetingMessage,
          });
          setMessages(prevState => [
            {role: 'assistant', message: greetingMessage},
            ...prevState,
          ]);
          const secondMessage = 'How are you feeling today?';
          await insertGeneralMessage({
            role: 'assistant',
            message: secondMessage,
          });
          setMessages(prevState => [
            {role: 'assistant', message: secondMessage},
            ...prevState,
          ]);
          setLastGreeted(currentDate);
        }
      } catch (error) {
        console.error('Error checking/storing greeting message date:', error);
      }
    };

    setTimeout(() => {
      checkAndShowGreetingMessage();
    }, 1000);
  }, []);

  const [shareMessage, setShareMessage] = useState<string | null>(null);
  const cardRef = useRef<View>(null);

  const handleShareAsImage = async (message: string) => {
    setShareMessage(message);
    setTimeout(async () => {
      try {
        if (!cardRef.current) return;
        const uri = await captureRef(cardRef, {
          format: 'png',
          quality: 1,
        });
        await Share.open({
          url: uri,
          type: 'image/png',
        });
      } catch (error) {
        console.error('Error capturing and sharing:', error);
      } finally {
        setShareMessage(null);
      }
    }, 100);
  };

  // Hide predefined questions when user starts typing
  useEffect(() => {
    if (userInput.trim()) {
      setShowPredefinedQuestions(false);
    }
  }, [userInput]);

  // Show predefined questions initially if no messages
  useEffect(() => {
    if (messages.length === 0) {
      setShowPredefinedQuestions(true);
    } else {
      setShowPredefinedQuestions(false);
    }
  }, [messages.length]);
  useEffect(() => {
    const loadMessages = async () => {
      try {
        const records = await fetchGeneralMessages();
        setMessages(records);
      } catch (error) {
        console.error(error);
      }
    };
    loadMessages();
  }, []);

  const renderMessage = (item: any, index: number) => {
    const reversedIndex = messages.length - 1 - index;
    return (
      <View
        key={reversedIndex}
        style={[
          styles.messageContainer,
          item.role === 'user' && styles.userMessageContainer,
        ]}>
        <View
          style={[
            styles.chatBubble,
            item.role === 'user' && styles.sentBubble,
          ]}>
          <Text
            style={[styles.chatText, item.role === 'user' && styles.sentText]}>
            {item.message}
          </Text>
        </View>
        {item.role === 'assistant' && (
          <IconButton
            icon={() => <LucideShare size={16} color="#6B7280" />}
            size={20}
            onPress={() => handleShareAsImage(item.message)}
            style={styles.shareButton}
          />
        )}
      </View>
    );
  };

  return (
    <KeyboardAvoidingView
      style={styles.container}
      behavior={Platform.OS === 'ios' ? 'padding' : 'padding'}>
      <StatusBar
        backgroundColor={Colors.lightGreen}
        barStyle={'light-content'}
      />
      <MainHeader
        isEmodeOn={true}
        onPressEmode={() => props.navigation.goBack()}
        isChatBarHide={false}
        showBackButton={false}
        nextButtonText="Quick Questions"
        onNextPress={() => {
          // Handle custom predefined questions action
          setShowPredefinedQuestions(!showPredefinedQuestions);
        }}
      />

      {/* Predefined Questions */}
      {showPredefinedQuestions && (
        <View style={styles.predefinedQuestionsContainer}>
          <Text style={styles.predefinedQuestionsTitle}>
            Quick Start Questions
          </Text>
          {PREDEFINED_QUESTIONS.map((question, index) => (
            <TouchableOpacity
              key={index}
              style={styles.predefinedQuestionButton}
              onPress={() => handlePredefinedQuestion(question)}>
              <Text style={styles.predefinedQuestionText}>{question}</Text>
            </TouchableOpacity>
          ))}
        </View>
      )}

      <FlatList
        ref={flatListRef}
        data={messages}
        initialScrollIndex={0}
        getItemLayout={(_, index) => ({
          length: 100,
          offset: 100 * index,
          index,
        })}
        inverted
        renderItem={({item, index}) => renderMessage(item, index)}
        keyExtractor={(_, index) => index.toString()}
        contentContainerStyle={styles.chatContainer}
        showsVerticalScrollIndicator={false}
      />
      {loading && (
        <View style={styles.loadingContainer}>
          <Spinner
            isVisible={true}
            size={32}
            type={'ThreeBounce'}
            color={Colors.lightGreen}
          />
        </View>
      )}
      <View style={styles.footer}>
        <View style={styles.inputContainer}>
          <TextInput
            value={userInput}
            onChangeText={setUserInput}
            placeholder="Type your message..."
            mode="outlined"
            outlineStyle={styles.textInputOutline}
            style={styles.textInput}
            multiline={true}
            dense={true}
            contentStyle={styles.textInputContent}
            placeholderTextColor="#9CA3AF"
          />
          {loading ? (
            <IconButton
              icon={() => <LucideSquare size={20} color="#FFFFFF" />}
              size={24}
              onPress={handleStop}
              style={[styles.sendButton, styles.stopButton]}
            />
          ) : (
            <IconButton
              icon={() => <LucideSend size={20} color="#FFFFFF" />}
              size={24}
              onPress={sendMessage}
              style={styles.sendButton}
            />
          )}
        </View>
        <SafeAreaView />
      </View>

      {shareMessage ? (
        <>
          <View style={styles.hiddenCard}>
            <ChatCard
              ref={cardRef}
              message={shareMessage}
              userName={userData?.displayName || ''}
            />
          </View>
        </>
      ) : null}
    </KeyboardAvoidingView>
  );
};

export default Chat;
