import React, {useState, useEffect} from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
} from 'react-native';
import MaterialIcons from 'react-native-vector-icons/MaterialIcons';
import {PostActivityConfig} from '@/data/videoData';

interface TextInputActivityProps {
  activity: PostActivityConfig;
  response?: string | string[];
  onResponseChange: (response: string | string[]) => void;
}

const TextInputActivity: React.FC<TextInputActivityProps> = ({
  activity,
  response,
  onResponseChange,
}) => {
  const [currentInput, setCurrentInput] = useState('');
  const [responses, setResponses] = useState<string[]>(
    Array.isArray(response) ? response : response ? [response] : [],
  );

  useEffect(() => {
    if (activity.hasAddMore) {
      onResponseChange(responses);
    } else {
      onResponseChange(responses[0] || '');
    }
  }, [responses, activity.hasAddMore, onResponseChange]);

  const addResponse = () => {
    if (currentInput.trim()) {
      setResponses(prev => [...prev, currentInput.trim()]);
      setCurrentInput('');
    }
  };

  const removeResponse = (index: number) => {
    setResponses(prev => prev.filter((_, i) => i !== index));
  };

  const updateSingleResponse = (text: string) => {
    setResponses([text]);
  };

  return (
    <View style={styles.container}>
      {activity.examples && (
        <View style={styles.examplesContainer}>
          <Text style={styles.examplesTitle}>Examples:</Text>
          {activity.examples.map((example, index) => (
            <Text key={index} style={styles.exampleText}>
              • {example}
            </Text>
          ))}
        </View>
      )}

      {activity.hasAddMore ? (
        <View>
          {/* Display existing responses */}
          {responses.map((resp, index) => (
            <View key={index} style={styles.responseItem}>
              <Text style={styles.responseText}>{resp}</Text>
              <TouchableOpacity
                onPress={() => removeResponse(index)}
                style={styles.removeButton}>
                <MaterialIcons name="close" size={16} color="#FF5252" />
              </TouchableOpacity>
            </View>
          ))}

          {/* Input for new response */}
          <View style={styles.inputContainer}>
            <TextInput
              style={styles.textInput}
              placeholder="Type your response..."
              value={currentInput}
              onChangeText={setCurrentInput}
              multiline
              numberOfLines={3}
              textAlignVertical="top"
            />
            <TouchableOpacity
              style={[
                styles.addButton,
                !currentInput.trim() && styles.addButtonDisabled,
              ]}
              onPress={addResponse}
              disabled={!currentInput.trim()}>
              <Text style={styles.addButtonText}>Add</Text>
            </TouchableOpacity>
          </View>
        </View>
      ) : (
        <TextInput
          style={styles.singleTextInput}
          placeholder="Type your response..."
          value={responses[0] || ''}
          onChangeText={updateSingleResponse}
          multiline
          numberOfLines={4}
          textAlignVertical="top"
        />
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginTop: 0,
  },
  examplesContainer: {
    backgroundColor: '#F9FAFB',
    padding: 16,
    borderRadius: 12,
    marginBottom: 20,
    borderLeftWidth: 4,
    borderLeftColor: '#2D7D7A',
  },
  examplesTitle: {
    fontSize: 14,
    fontWeight: '600',
    color: '#374151',
    marginBottom: 8,
  },
  exampleText: {
    fontSize: 14,
    color: '#6B7280',
    marginBottom: 4,
    lineHeight: 20,
  },
  responseItem: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#ECFDF5',
    padding: 12,
    borderRadius: 8,
    marginBottom: 8,
  },
  responseText: {
    flex: 1,
    fontSize: 14,
    color: '#374151',
  },
  removeButton: {
    padding: 4,
    marginLeft: 8,
  },
  inputContainer: {
    flexDirection: 'row',
    alignItems: 'flex-end',
    marginTop: 16,
  },
  textInput: {
    flex: 1,
    borderWidth: 1,
    borderColor: '#E5E7EB',
    borderRadius: 8,
    padding: 12,
    fontSize: 14,
    maxHeight: 80,
    marginRight: 12,
    backgroundColor: '#FFFFFF',
  },
  addButton: {
    backgroundColor: '#2D7D7A',
    paddingHorizontal: 16,
    paddingVertical: 12,
    borderRadius: 8,
  },
  addButtonDisabled: {
    backgroundColor: '#D1D5DB',
  },
  addButtonText: {
    color: '#FFFFFF',
    fontWeight: '600',
    fontSize: 14,
  },
  singleTextInput: {
    borderWidth: 1,
    borderColor: '#E5E7EB',
    borderRadius: 8,
    padding: 16,
    fontSize: 14,
    minHeight: 100,
    backgroundColor: '#FFFFFF',
    textAlignVertical: 'top',
  },
});

export default TextInputActivity;
