import Button from '@/components/ui/buttons/button';
import AlertBox from '@/components/ui/modal/alert-box';
import TextBox from '@/components/ui/text-box/TextBox';
import {FONT_FAMILIES, lightTheme} from '@/constants';
import useAppStore from '@/core/stores';
import {useState} from 'react';
import {StyleSheet, Text, View} from 'react-native';
import {SelectList} from 'react-native-dropdown-select-list';
import Feather from 'react-native-vector-icons/Feather';

interface SymptomLogTimeProp {
  onNext: () => void;
}

const SymptomLogTime: React.FC<SymptomLogTimeProp> = ({onNext}) => {
  const {addQuiz} = useAppStore(state => state.engagement);

  const [time, setTime] = useState('');
  const [isTextBoxVisible, setTextBoxVisible] = useState(false);
  const [customTime, setCustomTime] = useState('');
  const [showAlert, setShowAlert] = useState(false);

  const timeList = [
    {label: '6pm', value: '6pm'},
    {label: '7pm', value: '7pm'},
    {label: '8pm', value: '8pm'},
    {label: '9pm', value: '9pm'},
    {label: '10pm', value: '10pm'},
    {label: 'Other', value: 'Other'},
  ];

  const onTimeSelect = (selectedTime: string) => {
    if (selectedTime === 'Other') {
      setTextBoxVisible(true);
      setTime('');
    } else {
      setTextBoxVisible(false);
      setTime(selectedTime);
      setCustomTime('');
    }
  };

  const onContinue = () => {
    const finalTime = isTextBoxVisible ? customTime : time;

    if (finalTime.trim()) {
      const data = {
        id: 22,
        question: `We can provide you with a form to record your symptoms at the end of each day. Please choose a time to log your symptoms.`,
        answer: finalTime,
      };
      addQuiz(data);
      onNext();
    } else {
      setShowAlert(true);
    }
  };
  return (
    <View style={styles.container}>
      <View style={styles.contentContainer}>
        <Text style={styles.titleText}>Daily Symptom Logging</Text>
        <Text style={styles.instructionText}>
          We can provide you with a form to record your symptoms at the end of
          each day. Please choose a time to log your symptoms.
        </Text>

        <View style={styles.selectContainer}>
          <SelectList
            data={timeList}
            setSelected={onTimeSelect}
            dropdownStyles={styles.dropdown}
            placeholder="Select log time..."
            maxHeight={300}
            inputStyles={styles.selectInput}
            searchPlaceholder=""
            searchicon={
              <Feather
                name="search"
                size={20}
                color={lightTheme.primary}
                style={{paddingRight: 12}}
              />
            }
            closeicon={
              <Feather name="x" size={20} color={lightTheme.primary} />
            }
            arrowicon={
              <Feather
                name="chevron-down"
                size={20}
                color={lightTheme.primary}
              />
            }
            boxStyles={styles.selectBox}
          />
        </View>
        {isTextBoxVisible && (
          <View style={styles.customTimeContainer}>
            <Text style={styles.customTimeLabel}>
              Enter your preferred time:
            </Text>
            <TextBox
              placeholder="e.g., 11pm, 6:30am"
              value={customTime}
              onChangeText={setCustomTime}
              style={styles.textInput}
              outlineColor={lightTheme.primary}
            />
          </View>
        )}
      </View>

      <View style={styles.buttonContainer}>
        <Button
          text="Continue"
          onPress={onContinue}
          backgroundColor={lightTheme.primary}
          textColor="white"
          style={styles.continueButton}
        />
      </View>
      <AlertBox
        visible={showAlert}
        message="Please specify the time"
        onClose={() => setShowAlert(false)}
        title="Error"
        onModalHide={() => {}}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    width: '100%',
    paddingHorizontal: 10,
  },
  contentContainer: {
    flex: 1,
    justifyContent: 'center',
  },
  titleText: {
    fontFamily: FONT_FAMILIES.LatoRegular,
    fontWeight: 'bold',
    fontSize: 24,
    color: lightTheme.textDark,
    textAlign: 'center',
    marginBottom: 20,
  },
  instructionText: {
    fontFamily: FONT_FAMILIES.LatoRegular,
    fontSize: 16,
    color: lightTheme.textMild,
    textAlign: 'center',
    lineHeight: 24,
    marginBottom: 30,
  },
  selectContainer: {
    marginBottom: 20,
  },
  selectBox: {
    borderRadius: 12,
    borderColor: lightTheme.primary,
    backgroundColor: 'white',
  },
  selectInput: {
    borderRadius: 12,
    color: lightTheme.textDark,
  },
  dropdown: {
    borderRadius: 12,
    backgroundColor: 'white',
    borderColor: lightTheme.primaryLight,
  },
  customTimeContainer: {
    marginTop: 20,
  },
  customTimeLabel: {
    fontSize: 16,
    fontFamily: FONT_FAMILIES.LatoRegular,
    color: lightTheme.textDark,
    marginBottom: 10,
    fontWeight: '600',
  },
  textInput: {
    backgroundColor: 'white',
    borderRadius: 12,
  },
  buttonContainer: {
    paddingBottom: 20,
  },
  continueButton: {
    width: '100%',
    height: 55,
  },
});

export default SymptomLogTime;
