import {lightTheme} from '@/constants/colors';
import FONT_FAMILIES from '@/constants/fonts';
import moment from 'moment';
import {
  Modal,
  Switch,
  Text,
  TouchableOpacity,
  TouchableWithoutFeedback,
  View,
  Platform,
} from 'react-native';
import AntDesign from 'react-native-vector-icons/AntDesign';
import DateTimePicker, {
  DateTimePickerEvent,
} from '@react-native-community/datetimepicker';
import {useState} from 'react';
import useAppStore from '@/core/stores';
import AlertBox from '@/components/ui/modal/alert-box';

interface LogPeriodModalProps {
  visible?: boolean;
  onRequestClose?: () => void;
  startDate: Date;
  onStartDateChange: (date: Date) => void;
  isToggleOn?: boolean;
  onTogglePress?: () => void;
}

const LogPeriodModal: React.FC<LogPeriodModalProps> = ({
  visible,
  onRequestClose,
  startDate,
  onStartDateChange,
  isToggleOn,
  onTogglePress,
}) => {
  const Colors = lightTheme;

  const [showDatePicker, setShowDatePicker] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Alert box states
  const [alertVisible, setAlertVisible] = useState(false);
  const [alertTitle, setAlertTitle] = useState('');
  const [alertMessage, setAlertMessage] = useState('');
  const [shouldCloseModal, setShouldCloseModal] = useState(false);

  const {getQuizWithID} = useAppStore(state => state.engagement);

  // Get cycle actions from store
  const {addPeriodDates, isLoading} = useAppStore(state => state.cycle);

  const showAlert = (title: string, message: string, shouldClose = false) => {
    setAlertTitle(title);
    setAlertMessage(message);
    setShouldCloseModal(shouldClose);
    setAlertVisible(true);
  };

  const handleDateChange = (
    event: DateTimePickerEvent,
    selectedDate?: Date,
  ) => {
    setShowDatePicker(Platform.OS === 'ios');

    if (event.type === 'set' && selectedDate) {
      onStartDateChange(selectedDate);
    }
  };

  const handleSave = async () => {
    try {
      setIsSaving(true);

      // Validate dates
      const start = moment(startDate);
      const end = moment(startDate).clone().add(4);

      const total_days = getQuizWithID(5)?.answer || 28;

      if (start.isAfter(end)) {
        showAlert('Invalid Dates', 'Start date cannot be after end date');
        return;
      }

      if (start.isAfter(moment())) {
        showAlert('Invalid Date', 'Start date cannot be in the future');
        return;
      }

      // Try to save using the store action
      await addPeriodDates(start, end, total_days);

      // If we get here, save was successful
      showAlert('Success', 'Period dates saved successfully', true);
    } catch (error) {
      console.error('Error saving period dates:', error);
      const errorMessage =
        error instanceof Error ? error.message : 'Unknown error occurred';
      showAlert('Error Saving Period Dates', errorMessage);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <>
      <Modal
        visible={visible}
        onRequestClose={onRequestClose}
        animationType="slide"
        transparent={true}>
        <View
          style={{
            flex: 1,
            justifyContent: 'center',
            alignItems: 'center',
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
          }}>
          <View
            style={{
              borderRadius: 20,
              backgroundColor: 'white',
              paddingHorizontal: 15,
              width: '90%',
              paddingVertical: 30,
            }}>
            <View
              style={{
                flexDirection: 'row',
                width: '100%',
                alignItems: 'center',
                paddingBottom: 20,
              }}>
              <Text
                style={{
                  fontFamily: FONT_FAMILIES.YoungSerifRegular,
                  fontSize: 20,
                  width: '80%',
                  paddingLeft: '20%',
                  textAlign: 'center',
                }}>
                Edit Period Date
              </Text>
              <TouchableOpacity
                onPress={onRequestClose}
                style={{width: '10%', marginLeft: 'auto'}}>
                <Text
                  style={{
                    fontSize: 20,
                    fontFamily: FONT_FAMILIES.YoungSerifRegular,
                  }}>
                  ✕
                </Text>
              </TouchableOpacity>
            </View>
            <View
              style={{
                flexDirection: 'row',
                paddingLeft: 10,
                paddingBottom: 10,
              }}>
              <Text style={{fontSize: 16, padding: 11}}>
                Cycle Start Date :
              </Text>
              <TouchableWithoutFeedback onPress={() => setShowDatePicker(true)}>
                <View
                  style={{
                    borderWidth: 1,
                    borderColor: '#eeeeee',
                    borderRadius: 12,
                    flexDirection: 'row',
                    marginLeft: 'auto',
                    marginRight: 45,
                    justifyContent: 'center',
                    alignItems: 'center',
                    paddingRight: 20,
                  }}>
                  <AntDesign
                    name="calendar"
                    size={18}
                    color={'black'}
                    style={{padding: 11}}
                  />
                  <Text style={{fontSize: 16}}>
                    {moment(startDate).format('DD/MM/YYYY')}
                  </Text>
                </View>
              </TouchableWithoutFeedback>
            </View>
            <View
              style={{
                flexDirection: 'row',
                paddingLeft: 10,
                paddingBottom: 15,
              }}>
              <Text style={{fontSize: 16, padding: 11}}>Irregular Periods</Text>
              <Switch
                trackColor={{false: '#767577', true: Colors.primary}}
                onValueChange={onTogglePress}
                value={isToggleOn}
                style={{marginLeft: 'auto', marginRight: 45}}
              />
            </View>
            <View
              style={{flexDirection: 'row', justifyContent: 'space-around'}}>
              <TouchableOpacity
                onPress={onRequestClose}
                disabled={isSaving || isLoading}
                style={{
                  width: '40%',
                  justifyContent: 'center',
                  alignItems: 'center',
                  borderRadius: 12,
                  backgroundColor: '#DDF7F4',
                  opacity: isSaving || isLoading ? 0.6 : 1,
                }}>
                <Text
                  style={{
                    fontFamily: FONT_FAMILIES.YoungSerifRegular,
                    fontSize: 16,
                    padding: 6,
                  }}>
                  Cancel
                </Text>
              </TouchableOpacity>
              <TouchableOpacity
                onPress={handleSave}
                disabled={isSaving || isLoading}
                style={{
                  width: '40%',
                  justifyContent: 'center',
                  alignItems: 'center',
                  borderRadius: 12,
                  backgroundColor: Colors.primary,
                  opacity: isSaving || isLoading ? 0.6 : 1,
                }}>
                <Text
                  style={{
                    fontFamily: FONT_FAMILIES.YoungSerifRegular,
                    fontSize: 16,
                    padding: 6,
                    color: 'white',
                  }}>
                  {isSaving || isLoading ? 'Saving...' : 'Save'}
                </Text>
              </TouchableOpacity>
            </View>

            {/* Single Date Picker component for both start and end dates */}
            {showDatePicker && (
              <DateTimePicker
                value={startDate} 
                mode="date"
                display={Platform.OS === 'ios' ? 'spinner' : 'default'}
                onChange={handleDateChange}
                textColor={Platform.OS === 'ios' ? '#000000' : undefined}
                accentColor={Platform.OS === 'ios' ? Colors.primary : undefined}
                themeVariant={Platform.OS === 'ios' ? 'light' : undefined}
              />
            )}
          </View>
        </View>
      </Modal>

      <AlertBox
        visible={alertVisible}
        title={alertTitle}
        message={alertMessage}
        onClose={() => {
          setAlertVisible(false);
          if (shouldCloseModal) {
            setShouldCloseModal(false);
          }
        }}
        onModalHide={() => {
          if (shouldCloseModal && onRequestClose) {
            onRequestClose();
          }
        }}
      />
    </>
  );
};

export default LogPeriodModal;
