import Button from '@/components/ui/buttons/button';
import AlertBox from '@/components/ui/modal/alert-box';
import moment from 'moment';
import {useState} from 'react';
import {Text, View, StyleSheet} from 'react-native';
import {SelectList} from 'react-native-dropdown-select-list';
import Feather from 'react-native-vector-icons/Feather';
import DateTimePicker, {
  DateTimePickerEvent,
} from '@react-native-community/datetimepicker';
import {FONT_FAMILIES, lightTheme} from '@/constants';
import useAppStore from '@/core/stores';

interface MensusDetailsProps {
  onNext: () => void;
}

const MensusDetails: React.FC<MensusDetailsProps> = ({onNext}) => {
  const {addQuiz, getQuizWithID} = useAppStore(state => state.engagement);
  const {addPeriodDates} = useAppStore(state => state.cycle);

  const [noOfDays, setNoOfDays] = useState<number>();
  const [dates, setDates] = useState<moment.Moment | undefined>(undefined);

  // Alert box states
  const [alertVisible, setAlertVisible] = useState(false);
  const [alertTitle, setAlertTitle] = useState('');
  const [alertMessage, setAlertMessage] = useState('');
  const [alertAction, setAlertAction] = useState<(() => void) | null>(null);

  const datesList = [
    ...Array.from({length: 30}, (_, i) => ({
      label: `${i + 21}`,
      value: i + 21,
    })),
    {label: '50+', value: 50},
  ];

  const [dateOption, setDateOption] = useState('I know');
  const [isDateModalVisible, setDateModalVisible] = useState(false);
  const [selected, setSelected] = useState('');

  const showAlert = (title: string, message: string, action?: () => void) => {
    setAlertTitle(title);
    setAlertMessage(message);
    setAlertAction(() => action);
    setAlertVisible(true);
  };

  const onSelect = (value: string) => {
    if (value !== `I don't know`) {
      setDateModalVisible(true);
    } else {
      setSelected(`I don't know`);
      setDates(undefined);
      setDateOption('I know');
    }
  };

  const onDateChange = (event: DateTimePickerEvent, date?: Date) => {
    if (date) {
      const mDate = moment(date.toString());
      const opt = `I know${mDate ? ` (${mDate.format('MMM DD')})` : ''}`;
      setDates(mDate);
      setSelected(opt);
      setDateOption(opt);
    }
    setDateModalVisible(false);
  };

  const onContinue = () => {
    if (selected && noOfDays) {
      const periodRegularity = {
        id: 5,
        question: `How often do you get your period? (e.g., every 31 days)`,
        answer: noOfDays,
      };
      const expectedNextCycleDate = {
        id: 6,
        question: `When is your next cycle expected to start?`,
        answer: selected,
      };
      addQuiz(periodRegularity);
      addQuiz(expectedNextCycleDate);
      if (dates === undefined) {
        showAlert(
          'Message',
          'No problem! By using our app, we can help you figure it out!',
          onNext,
        );
      } else {
        const cycle_days = getQuizWithID(5)?.answer || 28;

        addPeriodDates(dates, dates.clone().add(4, 'days'), cycle_days);
        onNext();
      }
    } else {
      showAlert('Error', 'Please answer all the questions');
    }
  };

  return (
    <>
      <View style={styles.container}>
        <View style={styles.questionContainer}>
          <Text style={styles.questionText}>
            How often do you get your period? (e.g., every 31 days)
          </Text>

          <SelectList
            data={datesList}
            setSelected={setNoOfDays}
            dropdownStyles={styles.dropdown}
            placeholder="Select the number of days..."
            maxHeight={300}
            inputStyles={styles.selectInput}
            searchPlaceholder=""
            searchicon={
              <Feather
                name="search"
                size={20}
                color={lightTheme.primary}
                style={{paddingRight: 12}}
              />
            }
            closeicon={
              <Feather name="x" size={20} color={lightTheme.primary} />
            }
            arrowicon={
              <Feather
                name="chevron-down"
                size={20}
                color={lightTheme.primary}
              />
            }
            boxStyles={styles.selectBox}
          />
        </View>

        <View style={styles.questionContainer}>
          <Text style={styles.questionText}>
            When do you expect your next menstrual cycle to start? (i.e., first
            day of menstrual bleeding)
          </Text>

          <View style={styles.radioContainer}>
            <Button
              text={dateOption}
              onPress={() => onSelect(dateOption)}
              backgroundColor={
                selected.includes('I know') ? lightTheme.primary : 'white'
              }
              textColor={
                selected.includes('I know') ? 'white' : lightTheme.textDark
              }
              style={[
                styles.radioButton,
                selected.includes('I know')
                  ? styles.selectedButton
                  : styles.unselectedButton,
              ]}
            />
            <Button
              text="I don't know"
              onPress={() => onSelect("I don't know")}
              backgroundColor={
                selected === "I don't know" ? lightTheme.primary : 'white'
              }
              textColor={
                selected === "I don't know" ? 'white' : lightTheme.textDark
              }
              style={[
                styles.radioButton,
                selected === "I don't know"
                  ? styles.selectedButton
                  : styles.unselectedButton,
              ]}
            />
          </View>
        </View>

        <View style={styles.buttonContainer}>
          <Button
            text="Continue"
            onPress={onContinue}
            backgroundColor={lightTheme.primary}
            textColor="white"
            style={styles.continueButton}
          />
        </View>

        {isDateModalVisible && (
          <DateTimePicker
            value={new Date(dates ? dates.format('YYYY-MM-DD') : new Date())}
            mode="date"
            display="default"
            onChange={onDateChange}
          />
        )}
      </View>

      <AlertBox
        visible={alertVisible}
        title={alertTitle}
        message={alertMessage}
        onClose={() => {
          setAlertVisible(false);
          if (alertAction) {
            alertAction();
            setAlertAction(null);
          }
        }}
        onModalHide={() => {}}
      />
    </>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    width: '100%',
    paddingHorizontal: 10,
  },
  questionContainer: {
    marginBottom: 30,
  },
  questionText: {
    fontFamily: FONT_FAMILIES.LatoRegular,
    fontWeight: 'bold',
    fontSize: 20,
    color: lightTheme.textDark,
    textAlign: 'center',
    marginBottom: 20,
    lineHeight: 28,
  },
  selectBox: {
    borderRadius: 12,
    borderColor: lightTheme.primary,
    backgroundColor: 'white',
  },
  selectInput: {
    borderRadius: 12,
    color: lightTheme.textDark,
  },
  dropdown: {
    borderRadius: 12,
    backgroundColor: 'white',
    borderColor: lightTheme.primaryLight,
  },
  radioContainer: {
    alignItems: 'center',
  },
  radioButton: {
    width: '100%',
    marginBottom: 15,
    height: 55,
  },
  selectedButton: {
    borderWidth: 2,
    borderColor: lightTheme.primary,
  },
  unselectedButton: {
    borderWidth: 1,
    borderColor: lightTheme.buttonBorder,
  },
  buttonContainer: {
    flex: 1,
    justifyContent: 'flex-end',
    paddingBottom: 20,
  },
  continueButton: {
    width: '100%',
    height: 55,
  },
});

export default MensusDetails;
