import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  Image,
  StatusBar,
} from 'react-native';
import {useNavigation, RouteProp} from '@react-navigation/native';
import VideoCalendarActivityComponent from '../../components/learn/activity/CalendarActivity';
import VideoRatingScaleActivityComponent from '../../components/learn/activity/RatingScaleActivityComponent';
import ReviewCardActivityComponent from '../../components/learn/activity/ReviewCardActivityComponent';
import MultipleChoiceActivityComponent from '../../components/learn/activity/MultipleChoiceActivityComponent';
import BackButton from '@/components/ui/buttons/back-button';
import {safeImageUri} from '@/utils/image-utils';
import TextInputActivity from '@/components/post-activites/TextInput';
import ChecklistActivity from '@/components/post-activites/ChecklistActivity';
import FONT_FAMILIES from '@/constants/fonts';

const getRandomAbstract = () =>
  `https://source.unsplash.com/400x220/?abstract,nature,water,pattern,random&sig=${Math.floor(
    Math.random() * 1000,
  )}`;

type ActivityDetailsScreenProps = {
  route: RouteProp<
    {
      params: {
        activity: any;
        activityType: any;
        title: any;
        thumbnailUrl?: any;
      };
    },
    'params'
  >;
};

const ActivityDetailsScreen = ({route}: ActivityDetailsScreenProps) => {
  const navigation = useNavigation();
  const {activity, activityType, title, thumbnailUrl} = route.params;
  const thumbnail = thumbnailUrl || getRandomAbstract();

  return (
    <View style={styles.container}>
      <StatusBar backgroundColor="#FFFFFF" barStyle="dark-content" />
      <View style={styles.header}>
        <BackButton onPress={() => navigation.goBack()} />
        <Text style={styles.headerTitle} numberOfLines={1}>
          {title}
        </Text>
      </View>
      <ScrollView
        style={styles.scrollContainer}
        contentContainerStyle={styles.scrollContentContainer}>
        <Image source={safeImageUri(thumbnail)} style={styles.thumbnail} />
        <View style={styles.contentContainer}>
          <Text style={styles.title}>{activity.question}</Text>
          <Text style={styles.description}>{activity.description}</Text>
        </View>
        <View style={styles.activityContainer}>
          {(() => {
            // Normalize the activity type by removing "Activity: " prefix and converting to lowercase
            const normalizedType = activityType
              .replace(/^Activity:\s*/i, '')
              .toLowerCase()
              .replace(/\s+/g, '_');

            switch (normalizedType) {
              case 'calendar':
                return (
                  <VideoCalendarActivityComponent
                    activity={activity}
                    onResponseChange={response => {
                      console.log(
                        'Calendar activity response changed:',
                        response,
                      );
                    }}
                  />
                );
              case 'rating_scale':
                return (
                  <VideoRatingScaleActivityComponent
                    activity={activity}
                    onResponseChange={response => {
                      console.log('Rating scale response changed:', response);
                    }}
                  />
                );
              case 'text':
              case 'question':
                return (
                  <TextInputActivity
                    activity={activity}
                    onResponseChange={response => {
                      console.log('Text input response changed:', response);
                    }}
                  />
                );
              case 'checklist':
                return (
                  <ChecklistActivity
                    activity={activity}
                    onResponseChange={response => {
                      console.log('Checklist response changed:', response);
                    }}
                  />
                );
              case 'multiple_choice':
                return (
                  <MultipleChoiceActivityComponent
                    activity={activity}
                    onResponseChange={response => {
                      console.log(
                        'Multiple choice response changed:',
                        response,
                      );
                    }}
                  />
                );
              case 'review_card':
                return (
                  <ReviewCardActivityComponent
                    activity={activity}
                    onResponseChange={response => {
                      console.log('Review card response changed:', response);
                    }}
                  />
                );
              default:
                return (
                  <View style={styles.fallbackContainer}>
                    <Text style={styles.fallbackText}>
                      Activity type "{normalizedType}" is not yet supported.
                    </Text>
                    <Text style={styles.fallbackSubtext}>
                      Original type: {activityType}
                    </Text>
                  </View>
                );
            }
          })()}
        </View>
      </ScrollView>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#FFFFFF',
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 20,
    paddingTop: 60,
    paddingBottom: 20,
    backgroundColor: '#FFFFFF',
    borderBottomWidth: 1,
    borderBottomColor: '#F3F4F6',
  },
  headerTitle: {
    fontSize: 20,
    fontWeight: '600',
    color: '#1F2937',
    marginLeft: 16,
    flex: 1,
    fontFamily: FONT_FAMILIES.YoungSerifRegular,
  },
  scrollContainer: {
    flex: 1,
  },
  scrollContentContainer: {
    paddingBottom: 32,
  },
  thumbnail: {
    width: '100%',
    height: 200,
    resizeMode: 'cover',
  },
  contentContainer: {
    padding: 20,
  },
  title: {
    fontSize: 24,
    fontWeight: '600',
    color: '#1F2937',
    marginBottom: 12,
    fontFamily: FONT_FAMILIES.YoungSerifRegular,
    lineHeight: 32,
  },
  description: {
    fontSize: 16,
    color: '#6B7280',
    lineHeight: 24,
  },
  activityContainer: {
    paddingHorizontal: 20,
  },
  reviewCardContainer: {
    backgroundColor: '#F9FAFB',
    borderRadius: 12,
    padding: 20,
    marginVertical: 16,
    borderLeftWidth: 4,
    borderLeftColor: '#2D7D7A',
  },
  reviewCardText: {
    fontSize: 16,
    color: '#374151',
    lineHeight: 24,
    fontFamily: FONT_FAMILIES.LatoRegular,
  },
  fallbackContainer: {
    backgroundColor: '#FEF2F2',
    borderRadius: 12,
    padding: 20,
    marginVertical: 16,
    borderLeftWidth: 4,
    borderLeftColor: '#EF4444',
  },
  fallbackText: {
    fontSize: 16,
    color: '#B91C1C',
    fontWeight: '600',
    marginBottom: 8,
    fontFamily: FONT_FAMILIES.MerriweatherBold,
  },
  fallbackSubtext: {
    fontSize: 14,
    color: '#6B7280',
    fontFamily: FONT_FAMILIES.LatoRegular,
  },
});

export default ActivityDetailsScreen;
