import FONT_FAMILIES from '@/constants/fonts';
import {
  deleteLastUpdatedSypmtomRecord,
  insertSymptomTrackerRecord,
} from '@/services/sqlite/feminine-health';
import useAppStore from '@/core/stores';
import React from 'react';
import {StyleSheet, Text, View} from 'react-native';
import {RectButton} from 'react-native-gesture-handler';
import Colors from '@/constants/colors';

interface SymptomsBoxsProps {
  name: string;
  bgColor: string;
  textColor: string;
  symptomType: 'Physical Symptom' | 'Psychological Symptom';
  count?: number;
  onSymptomUpdate?: () => Promise<void>; // Add this
}

const SymptomsBoxs = ({
  name,
  bgColor,
  textColor,
  symptomType,
  count = 0,
  onSymptomUpdate, // Add this
}: SymptomsBoxsProps) => {
  const {updateDailySymptomCount} = useAppStore(state => state.recent_symptom);

  const handlePress = async () => {
    const newCount = count + 1;

    try {
      await insertSymptomTrackerRecord({
        symptom_type: symptomType,
        symptom: name,
        count: newCount,
      });

      updateDailySymptomCount(symptomType, name, newCount);

      // Refresh the data from database
      if (onSymptomUpdate) {
        await onSymptomUpdate();
      }
    } catch (error) {
      console.error('Error logging symptom:', error);
    }
  };

  const handleLongPress = async () => {
    try {
      const newCount = count === 0 ? 0 : count - 1;
      await deleteLastUpdatedSypmtomRecord(name, symptomType, count);
      updateDailySymptomCount(symptomType, name, newCount);
    } catch (error) {
      console.error(error);
    }
  };

  return (
    <RectButton
      onPress={handlePress}
      onLongPress={handleLongPress}
      style={[
        styles.container,
        {backgroundColor: bgColor, borderColor: bgColor},
      ]}>
      <Text style={[styles.nameText, {color: textColor}]}>{name}</Text>
      {count > 0 && (
        <View style={styles.badge}>
          <Text style={styles.badgeText}>{count}</Text>
        </View>
      )}
    </RectButton>
  );
};

const styles = StyleSheet.create({
  container: {
    borderRadius: 20,
    marginRight: 8,
    marginBottom: 12,
    paddingHorizontal: 18,
    paddingVertical: 8,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#eee',
  },
  nameText: {
    fontSize: 16,
    fontWeight: 'bold',
    fontFamily: FONT_FAMILIES.LatoRegular,
    textAlign: 'center',
  },
  badge: {
    position: 'absolute',
    right: -2,
    top: -8,
    backgroundColor: '#ff607bff',
    borderRadius: 20,
    paddingHorizontal: 6,
    paddingVertical: 2,
    alignItems: 'center',
    justifyContent: 'center',
  },
  badgeText: {
    color: 'white',
    fontSize: 14,
    fontWeight: 'bold',
  },
});

export default SymptomsBoxs;
