import MainHeader from '@/components/common/headers/MainHeader';
import LogActionButton from '@/components/common/log-action-button';
import Colors, {lightTheme} from '@/constants/colors';
import useAppStore from '@/core/stores';
import {
  fetchCycleRecordByDate,
  fetchSymptomRecordCounts,
  initializeFeminineHealthDatabase,
  insertSymptomTrackerRecord,
} from '@/services/sqlite/feminine-health';
import {Toast} from '@/utils/toast';
import {useEffect, useMemo, useRef, useState} from 'react';
import {Animated, ScrollView, Text, TouchableOpacity, View} from 'react-native';
import SizeBox from '../../components/common/size-box';
import DaysChart from './components/DaysChart';
import SymptomsBoxs from './components/SymptomsBoxs';
import Styles from './HomeStyle';
import {
  DEFAULT_PHYSICAL,
  DEFAULT_PSYCHOLOGICAL,
  MoodList,
  PHYSICAL_SYMPTOMS_FULL,
  PSYCHOLOGICAL_SYMPTOMS_FULL,
} from './home.constants';
import moment from 'moment';

type CycleRecord = {
  id?: string;
  date: string;
  color: string;
  start_date?: number;
  end_date?: number;
  is_last_date?: number;
  day: number;
};

const Home = ({navigation}: any) => {
  const [isFabOpen, setIsFabOpen] = useState(false);
  const rotation = useRef(new Animated.Value(0)).current;
  const blurOpacity = useRef(new Animated.Value(0)).current;

  // Zustand store for symptoms & mood
  const {
    currentMood,
    dailySymptomsCount,
    setCurrentMood,
    resetCurrentMood,
    updateDailySymptomCount,
    loadDailySymptomsFromStorage,
    loadEmojiStateFromStorage,
    loadRecentSymptomsFromStorage,
    clearEmojiTimeout,
  } = useAppStore(state => state.recent_symptom);

  const [isDatabaseInitialized, setIsDatabaseInitialized] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [todayRecord, setTodayRecord] = useState<CycleRecord | undefined>(
    undefined,
  );

  // Get cycle data and actions from Zustand store
  const {fetchCycleData} = useAppStore(state => state.cycle);

  // Generate recently used symptoms based on today's counts
  const recentSymptoms = useMemo(() => {
    const symptoms: Array<{
      name: string;
      type: 'physical' | 'psychological';
      count: number;
    }> = [];

    // Add physical symptoms with counts > 0
    const physicalCounts = dailySymptomsCount?.['Physical Symptom'] || {};
    Object.entries(physicalCounts).forEach(([symptom, count]) => {
      if (count > 0) {
        symptoms.push({name: symptom, type: 'physical', count});
      }
    });

    // Add psychological symptoms with counts > 0
    const psychologicalCounts =
      dailySymptomsCount?.['Psychological Symptom'] || {};
    Object.entries(psychologicalCounts).forEach(([symptom, count]) => {
      if (count > 0) {
        symptoms.push({name: symptom, type: 'psychological', count});
      }
    });

    // Sort by count (descending) and limit to 6
    return symptoms.sort((a, b) => b.count - a.count).slice(0, 6);
  }, [dailySymptomsCount]);

  // Mood logging
  const handleEmojisPress = async (id: string) => {
    if (!isDatabaseInitialized) {
      Toast('Database not ready. Please try again.');
      return;
    }

    try {
      const newMood = currentMood === id ? '' : id;

      if (newMood) {
        setCurrentMood(newMood);
      } else {
        resetCurrentMood();
      }

      const success = await insertSymptomTrackerRecord({
        symptom_type: 'Mood',
        symptom: id,
        count: 0,
      });

      if (success) {
        updateDailySymptomCount('Mood', id, 1);
        await loadSymptomCounts();
      }
    } catch (error) {
      console.error('Error logging mood:', error);
      Toast('Error logging mood');
    }
  };

  const optionAnimations = useRef([
    {
      opacity: new Animated.Value(0),
      translateY: new Animated.Value(50),
    },
    {
      opacity: new Animated.Value(0),
      translateY: new Animated.Value(50),
    },
    {
      opacity: new Animated.Value(0),
      translateY: new Animated.Value(50),
    },
  ]).current;

  const toggleFab = () => {
    const newState = !isFabOpen;
    setIsFabOpen(newState);

    Animated.timing(rotation, {
      toValue: newState ? 1 : 0,
      duration: 300,
      useNativeDriver: true,
    }).start();

    Animated.timing(blurOpacity, {
      toValue: newState ? 1 : 0,
      duration: 300,
      useNativeDriver: true,
    }).start();

    if (newState) {
      optionAnimations.forEach((anim, index) => {
        Animated.parallel([
          Animated.timing(anim.opacity, {
            toValue: 1,
            duration: 300,
            useNativeDriver: true,
            delay: 50 * index,
          }),
          Animated.timing(anim.translateY, {
            toValue: 0,
            duration: 300,
            useNativeDriver: true,
            delay: 50 * index,
          }),
        ]).start();
      });
    } else {
      optionAnimations.forEach(anim => {
        Animated.parallel([
          Animated.timing(anim.opacity, {
            toValue: 0,
            duration: 200,
            useNativeDriver: true,
          }),
          Animated.timing(anim.translateY, {
            toValue: 50,
            duration: 200,
            useNativeDriver: true,
          }),
        ]).start();
      });
    }
  };

  const loadSymptomCounts = async () => {
    if (!isDatabaseInitialized) return;
    try {
      const from = new Date();
      const to = new Date();
      from.setHours(0, 0, 0, 0);
      to.setHours(23, 59, 59, 999);

      // You may want to fetch for all symptoms, but here is a sample fetch
      // You can extend this to query all relevant symptoms as needed
      const counts = await fetchSymptomRecordCounts([
        ...PHYSICAL_SYMPTOMS_FULL.map(symptom => ({
          symptom,
          symptom_type: 'Physical Symptom',
          from,
          to,
        })),
        ...PSYCHOLOGICAL_SYMPTOMS_FULL.map(symptom => ({
          symptom,
          symptom_type: 'Psychological Symptom',
          from,
          to,
        })),
      ]);
      Object.entries(counts).forEach(([symptomType, symptoms]) => {
        Object.entries(symptoms as Record<string, number>).forEach(
          ([symptom, count]) => {
            updateDailySymptomCount(
              symptomType as
                | 'Physical Symptom'
                | 'Psychological Symptom'
                | 'Mood',
              symptom,
              count,
            );
          },
        );
      });
    } catch (error) {
      console.error('Error loading symptom counts:', error);
    }
  };

  useEffect(() => {
    const initializeApp = async () => {
      setIsLoading(true);
      try {
        const dbInitialized = await initializeFeminineHealthDatabase();
        if (!dbInitialized) {
          Toast('Database initialization failed');
          setIsLoading(false);
          return;
        }
        setIsDatabaseInitialized(true);
        loadDailySymptomsFromStorage();
        loadEmojiStateFromStorage();
        loadRecentSymptomsFromStorage();
        await loadSymptomCounts();
        await fetchCycleData();
      } catch (error) {
        console.error('Error during app initialization:', error);
        Toast('Error initializing app');
      } finally {
        setIsLoading(false);
      }
    };
    initializeApp();
  }, [
    fetchCycleData,
    loadDailySymptomsFromStorage,
    loadEmojiStateFromStorage,
    loadRecentSymptomsFromStorage,
  ]);

  useEffect(() => {
    return () => {
      clearEmojiTimeout();
    };
  }, [clearEmojiTimeout]);

  useEffect(() => {
    try {
      const date = moment().format('YYYY-MM-DD');
      fetchCycleRecordByDate(date)
        .then(val => {
          setTodayRecord(val);
        })
        .catch(err => {
          console.error(err);
        });
    } catch (error) {
      console.error(error);
    }
  }, [fetchCycleRecordByDate]);

  const refreshSymptomCounts = async () => {
    if (!isDatabaseInitialized) {
      return;
    }
    await loadSymptomCounts();
  };

  // Always show default symptoms for Physical and Psychological sections
  const physicalSymptomsToShow = DEFAULT_PHYSICAL;
  const psychologicalSymptomsToShow = DEFAULT_PSYCHOLOGICAL;

  if (isLoading) {
    return (
      <View
        style={[
          Styles.container,
          {justifyContent: 'center', alignItems: 'center'},
        ]}>
        <Text style={{fontSize: 18, color: Colors.black}}>Loading...</Text>
      </View>
    );
  }

  return (
    <View style={Styles.container}>
      <MainHeader
        isEmodeOn={true}
        showBackButton={false}
        onPressEmode={() => navigation.navigate('Emode')}
        onNextPress={() => navigation.navigate('Chat')}
      />

      <ScrollView
        contentContainerStyle={{flexGrow: 1}}
        overScrollMode="never"
        showsVerticalScrollIndicator={false}>
        <SizeBox height={20} />
        <DaysChart
          onPlusPress={() => navigation.navigate('Calendar')}
          todayRecord={todayRecord}
        />

        <SizeBox height={20} />
        <Text style={Styles.title}>Mood</Text>

        <View
          style={{
            height: 90,
            marginHorizontal: 10,
            flexDirection: 'row',
            alignItems: 'flex-start',
            justifyContent: 'space-between',
            paddingHorizontal: 5,
          }}>
          {MoodList.map(item => {
            const SvgComponent = item.SvgComponent;
            return (
              <TouchableOpacity
                key={item.id}
                style={{
                  zIndex: 1,
                  alignItems: 'center',
                  justifyContent: 'flex-start',
                  opacity:
                    currentMood !== '' && currentMood !== item.id ? 0.2 : 1,
                }}
                onPress={() => handleEmojisPress(item.id)}>
                <View
                  style={{
                    height: 60,
                    width: 60,
                    borderRadius: 30,
                    justifyContent: 'center',
                    alignItems: 'center',
                  }}>
                  <SvgComponent width={48} height={48} />
                </View>
                <Text
                  style={{
                    fontSize: 12,
                    color: Colors.black,
                    textAlign: 'center',
                    marginTop: 5,
                    fontWeight: 'normal',
                    fontFamily: 'Lato-Regular',
                  }}>
                  {item.MoodName}
                </Text>
              </TouchableOpacity>
            );
          })}
        </View>

        <SizeBox height={30} />

        {/* Recently Used Symptoms */}
        {recentSymptoms.length > 0 && (
          <>
            <Text style={Styles.title}>Recently Used Symptoms</Text>
            <View style={Styles.nameList}>
              {recentSymptoms.map(
                (recentSymptom: {
                  name: string;
                  type: 'physical' | 'psychological';
                  count: number;
                }) => (
                  <SymptomsBoxs
                    key={`${recentSymptom.type}-${recentSymptom.name}`}
                    name={recentSymptom.name}
                    bgColor={
                      recentSymptom.type === 'physical'
                        ? lightTheme.physicalSymptomBg
                        : lightTheme.psychologicalSymptomBg
                    }
                    textColor={Colors.black}
                    symptomType={
                      recentSymptom.type === 'physical'
                        ? 'Physical Symptom'
                        : 'Psychological Symptom'
                    }
                    count={recentSymptom.count}
                    onSymptomUpdate={refreshSymptomCounts}
                  />
                ),
              )}
            </View>
            <SizeBox height={20} />
          </>
        )}

        <Text style={Styles.title}>Physical Symptoms</Text>
        <View style={Styles.nameList}>
          {physicalSymptomsToShow.map(name => (
            <SymptomsBoxs
              key={name}
              name={name}
              bgColor={lightTheme.physicalSymptomBg}
              textColor={Colors.black}
              symptomType="Physical Symptom"
              count={dailySymptomsCount?.['Physical Symptom']?.[name] || 0}
              onSymptomUpdate={refreshSymptomCounts}
            />
          ))}
        </View>

        <SizeBox height={20} />

        <Text style={Styles.title}>Psychological Symptoms</Text>
        <View style={Styles.nameList}>
          {psychologicalSymptomsToShow.map(name => (
            <SymptomsBoxs
              key={name}
              name={name}
              bgColor={lightTheme.psychologicalSymptomBg}
              textColor={Colors.black}
              symptomType="Psychological Symptom"
              count={dailySymptomsCount?.['Psychological Symptom']?.[name] || 0}
              onSymptomUpdate={refreshSymptomCounts}
            />
          ))}
        </View>

        <SizeBox height={60} />
      </ScrollView>

      {/* Overlay instead of BlurView */}
      {isFabOpen && (
        <Animated.View
          style={[
            Styles.overlay,
            {
              opacity: blurOpacity,
            },
          ]}>
          <TouchableOpacity
            style={Styles.overlayTouchable}
            onPress={toggleFab}
            activeOpacity={1}
          />
        </Animated.View>
      )}

      <LogActionButton />
    </View>
  );
};

export default Home;
