import { ButtonGroup } from "@/components";
import { FONT_FAMILIES, lightTheme } from "@/constants";
import useAppStore from "@/core/stores";
import { Dimensions, Modal, StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { GestureHandlerRootView, ScrollView } from "react-native-gesture-handler";
import { useShallow } from "zustand/react/shallow";
import Ionicons from "react-native-vector-icons/Ionicons";
import { useState } from "react";
import TextInputComponent from "@/components/ui/inputs/text-input";
import { Toast } from "@/utils/toast";

const { width } = Dimensions.get('screen');

interface PreferenceModalProps{
    visible: boolean;
    onRequestClose: () => void;
}

const PreferenceModal: React.FC<PreferenceModalProps> = ({
    visible,
    onRequestClose
}) => {
  const [addPreferenceModalVisible, setAddPreferenceModalVisible] = useState(false);
  const [newPreference, setNewPreference] = useState('');
  const {preferences} = useAppStore(useShallow(state => state.engagement));
  const {
    addPreference, 
    removePreference, 
    clearPreference
  } = useAppStore(state => state.engagement);

  return(
    <View>
        <Modal
            visible={visible}
            onRequestClose={onRequestClose}
            animationType="slide"
            transparent={true}
        >
            <GestureHandlerRootView style={styles.mainContainer}>
                <View style={styles.innerContainer}>
                    <Text style={styles.titleText}>Preferences</Text>
                    <ScrollView style={styles.preferenceContainer}>
                        {preferences.map((preference) => (
                            <View style={{flexDirection: 'row', margin: 10, borderBottomColor: lightTheme.buttonBorder, borderBottomWidth: 1, justifyContent: 'center', alignItems: 'center', paddingBottom: 10}}>
                                <Text 
                                    style={{width: '90%', fontFamily: FONT_FAMILIES.LatoRegular, fontSize: 18}}
                                >
                                    {preference}
                                </Text>
                                <TouchableOpacity
                                    onPress={() => removePreference(preference)}
                                >
                                    <Ionicons 
                                        name="trash-outline"
                                        color={lightTheme.primary}
                                        size={width * 0.06}
                                    />
                                </TouchableOpacity>
                            </View>
                        ))}
                    </ScrollView>
                    <ButtonGroup 
                        TextStyle={styles.buttonText}
                        ButtonStyle={{width: '30%'}}
                        buttonProps={[{
                            text: "Add",
                            onPress: () => {
                                setAddPreferenceModalVisible(true);
                                onRequestClose();
                            }
                        }, {
                            text: "Clear",
                            onPress: () => {clearPreference()}
                        }, {
                            text: "Close",
                            onPress: onRequestClose
                        }]}
                        condtionFuntion={() => true}
                    />
                </View>
            </GestureHandlerRootView>
        </Modal>
        <Modal
            visible={addPreferenceModalVisible}
            onRequestClose={() => setAddPreferenceModalVisible(false)}
            animationType="slide"
            transparent={true}
        >
            <GestureHandlerRootView style={styles.mainContainer}>
                <View style={styles.innerContainer}>
                    <Text style={styles.titleText}>New Preferences</Text>
                    <TextInputComponent
                        value={newPreference}
                        onChangeText={setNewPreference}
                        containerStyle={{width: '100%'}}
                        inputStyle={{height: 100}}
                        multiline={true}
                    />
                    <ButtonGroup 
                        TextStyle={styles.buttonText}
                        ButtonStyle={{width: '30%'}}
                        buttonProps={[{
                            text: "Add",
                            onPress: () => {
                                if(newPreference){
                                    addPreference(newPreference)
                                    setAddPreferenceModalVisible(false);
                                }
                                else{
                                    Toast('Please enter preference.')
                                }
                            }
                        }, {
                            text: "Close",
                            onPress: () => setAddPreferenceModalVisible(false)
                        }]}
                    />
                </View>
            </GestureHandlerRootView>
        </Modal>
    </View>
  )
}

const styles = StyleSheet.create({
    mainContainer: {
        flex: 1,
        justifyContent: 'center',
        alignItems: 'center',
        backgroundColor: 'rgba(0, 0, 0, 0.5)',
    }, 
    innerContainer: {
        borderRadius: 20,
        backgroundColor: 'white',
        paddingHorizontal: 30,
        width: '90%',
        paddingVertical: 30,
        justifyContent: 'center',
        alignItems: 'center',
    },
    titleText: {
        fontSize: 18, 
        fontFamily: FONT_FAMILIES.YoungSerifRegular,
        paddingBottom: 15,
    },
    buttonText: {
        fontFamily: FONT_FAMILIES.YoungSerifRegular, 
        fontSize: 16,
    },
    preferenceContainer:{
        borderColor: lightTheme.buttonBorder,
        borderWidth: 1,
        borderRadius: 20,
        width: '100%',
        height: 300,
        marginBottom: 20,
    }
})

export default PreferenceModal;