import {
  ActivityResponse,
  TextActivity,
} from '@/core/stores/slices/playlist/types';
import React, {useEffect, useState} from 'react';
import {StyleSheet, Text, TextInput, View} from 'react-native';

interface TextActivityProps {
  activity: TextActivity;
  response?: ActivityResponse<TextActivity>;
  onResponseChange: (response: ActivityResponse<TextActivity>) => void;
}

const TextActivityComponent: React.FC<TextActivityProps> = ({
  activity,
  response,
  onResponseChange,
}) => {
  const [text, setText] = useState(response?.text || '');

  useEffect(() => {
    onResponseChange({text});
  }, [text, onResponseChange]);

  return (
    <View style={styles.container}>
      <Text style={styles.question}>{activity.question}</Text>
      {activity.description && (
        <Text style={styles.description}>{activity.description}</Text>
      )}

      {activity.examples && (
        <View style={styles.examplesContainer}>
          <Text style={styles.examplesTitle}>Examples:</Text>
          {activity.examples.map((example, index) => (
            <Text key={index} style={styles.exampleText}>
              • {example}
            </Text>
          ))}
        </View>
      )}

      <TextInput
        style={styles.textInput}
        placeholder="Type your response..."
        value={text}
        onChangeText={setText}
        multiline
        numberOfLines={4}
        textAlignVertical="top"
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginTop: 10,
  },
  question: {
    fontSize: 16,
    fontWeight: '600',
    marginBottom: 8,
    color: '#333',
  },
  description: {
    fontSize: 14,
    color: '#666',
    marginBottom: 16,
  },
  examplesContainer: {
    backgroundColor: '#F5F5F5',
    padding: 12,
    borderRadius: 8,
    marginBottom: 16,
  },
  examplesTitle: {
    fontSize: 14,
    fontWeight: '600',
    marginBottom: 8,
  },
  exampleText: {
    fontSize: 12,
    color: '#666',
    marginBottom: 4,
  },
  textInput: {
    borderWidth: 1,
    borderColor: '#E0E0E0',
    borderRadius: 8,
    padding: 12,
    minHeight: 100,
    fontSize: 14,
  },
});

export default TextActivityComponent;
